-- Model answers for question_bank
-- schema.sql already creates answer_text; run schema.sql before this file.
-- Shared questions are updated by question_text; role-specific ones by job_role + question_text.

BEGIN IMMEDIATE;

-- ===== SHARED QUESTIONS: BEHAVIORAL =====
UPDATE question_bank SET answer_text = 'Situation: a teammate and I disagreed on how to structure a release. Action: I asked to hear their reasoning first, then shared data supporting my view and proposed a small trial of both. Result: we picked the approach the trial favored, and the working relationship got stronger because the decision was evidence-based, not personal.' WHERE question_text = 'Tell me about a time you disagreed with a manager or teammate. How did you handle it?';
UPDATE question_bank SET answer_text = 'A client date moved up by a week. I broke the work into must-haves and nice-to-haves, aligned with my manager on scope, asked a colleague to take one dependent piece, and gave daily progress updates. We delivered the core on time and scheduled the rest as a fast follow-up.' WHERE question_text = 'Describe a situation where you had to meet a tight deadline. What did you do?';
UPDATE question_bank SET answer_text = 'I once shipped a report with a filter error that overstated a number. I noticed it within hours, told my manager immediately, corrected the report, and notified everyone who had received it. I then added a review checklist step so the same mistake could not recur.' WHERE question_text = 'Give an example of a time you made a mistake at work. How did you address it?';
UPDATE question_bank SET answer_text = 'A project needed a tool I had never used. I spent two evenings on the official docs and a small practice project, asked a colleague for a 30-minute walkthrough, and then built the real task in small steps with frequent check-ins. It was delivered on schedule and I now use the tool regularly.' WHERE question_text = 'Tell me about a time you had to learn something new quickly to complete a task.';
UPDATE question_bank SET answer_text = 'My manager told me my updates were too detailed and buried the key point. I felt defensive for a moment, then asked for an example of what good looked like. I started leading with the conclusion and next step, and later feedback said my updates were much easier to act on.' WHERE question_text = 'Describe a time you received difficult feedback. How did you respond?';
UPDATE question_bank SET answer_text = 'I am most proud of a project where I took a messy, manual process and redesigned it end to end. It cut turnaround time significantly and the team adopted it. I am proud because I owned the outcome, brought others along, and measured the impact instead of assuming it.' WHERE question_text = 'Tell me about a project you''re most proud of and why.';
UPDATE question_bank SET answer_text = 'I wanted to change a process my team was comfortable with. I learned what each person cared about, framed the change around their pain points, and ran a short pilot to show results. Once the numbers showed time saved, the team agreed to adopt it.' WHERE question_text = 'Describe a time you had to persuade someone to see things your way.';
UPDATE question_bank SET answer_text = 'An initiative I led missed its goal because I underestimated dependencies on another team. I owned it in the retrospective, documented what I missed, and now map dependencies and confirm commitments at kickoff. That habit has prevented similar slips since.' WHERE question_text = 'Tell me about a time you failed at something important. What did you learn?';
UPDATE question_bank SET answer_text = 'I noticed new joiners kept asking the same setup questions, so without being asked I wrote a short onboarding guide and shared it with the team. It reduced repeat questions and was later adopted as the official onboarding document.' WHERE question_text = 'Give an example of when you took initiative without being asked.';
UPDATE question_bank SET answer_text = 'A colleague preferred detailed written plans while I preferred quick conversations. We agreed on a middle path: a short written summary after each discussion. It gave them clarity and me speed, and it taught me to ask people how they work best.' WHERE question_text = 'Describe a time you had to work with someone whose working style was very different from yours.';
UPDATE question_bank SET answer_text = 'With several urgent requests landing together, I listed them, estimated impact and effort, and checked priorities with my manager. I handled the highest-impact item first, told other requesters realistic dates, and delegated or deferred the rest. Nothing slipped without people knowing.' WHERE question_text = 'Tell me about a time you had to prioritize multiple competing tasks.';
UPDATE question_bank SET answer_text = 'A customer-facing issue came up on a Friday evening. I stayed to diagnose it, worked out a fix, and wrote a short summary for the team so the weekend was quiet. The customer was kept informed throughout and later praised the quick resolution.' WHERE question_text = 'Describe a situation where you went above and beyond what was expected.';
UPDATE question_bank SET answer_text = 'A teammate''s work was missing a recurring requirement. I asked for a private conversation, described the specific impact, listened to their side, and offered to help with a checklist. They appreciated the directness, and the issue stopped recurring.' WHERE question_text = 'Tell me about a time you had to give someone unwelcome feedback.';
UPDATE question_bank SET answer_text = 'I had to choose a direction without complete data. I identified the key assumptions, quickly gathered the most important missing facts from people closest to the problem, chose the lowest-risk reversible option, and set a checkpoint to revisit. The decision held up and we adjusted slightly at the checkpoint.' WHERE question_text = 'Describe a time you had insufficient information to make a decision. What did you do?';
UPDATE question_bank SET answer_text = 'Two colleagues were in conflict over ownership of a task. I met each separately to understand their concerns, then brought them together to agree on clear responsibilities and a shared goal. The tension eased and we documented the split to avoid repeats.' WHERE question_text = 'Tell me about a time you managed a conflict between two colleagues.';
UPDATE question_bank SET answer_text = 'The hardest project had unclear requirements, a tight timeline and many stakeholders. I clarified goals first, split the work into milestones, kept a risk log, and communicated weekly. We shipped on time, and the stakeholder alignment I built became a template for later projects.' WHERE question_text = 'Describe the most challenging project you''ve worked on and how you handled it.';
UPDATE question_bank SET answer_text = 'A reviewer criticized part of my work in front of the team. I stayed calm, asked clarifying questions, and acknowledged the valid points. I fixed the issues the same day and followed up privately, which turned the critique into a better result and a better relationship.' WHERE question_text = 'Tell me about a time your work was criticized. How did you react?';
UPDATE question_bank SET answer_text = 'Priorities changed midway through a quarter. I reassessed what was already done, re-planned the remaining work with my manager, and communicated the revised timeline to stakeholders. By staying flexible and transparent, we delivered the new priority without losing the key earlier work.' WHERE question_text = 'Give an example of a time you had to adapt quickly to a change in plans.';
UPDATE question_bank SET answer_text = 'A stakeholder requested a feature that would have derailed our timeline. I explained the trade-offs with numbers, offered a smaller alternative and a later date for the full request. They appreciated the options, and we kept the release on track.' WHERE question_text = 'Describe a time you had to say no to a request. How did you handle it?';
UPDATE question_bank SET answer_text = 'A teammate was falling behind after joining mid-project. I set up short pairing sessions, shared my notes, and let them take ownership of a small piece first. Within weeks they were working independently and contributing ideas.' WHERE question_text = 'Tell me about a time you helped a struggling teammate.';
UPDATE question_bank SET answer_text = 'Early on I chose a quick workaround over a proper fix to hit a date, and it caused repeated issues later. Today I would raise the trade-off explicitly, get agreement on a follow-up fix with a date, and track it, rather than quietly accumulating the problem.' WHERE question_text = 'Describe a decision you made that you would make differently now.';
UPDATE question_bank SET answer_text = 'During a critical launch week, several issues surfaced at once. I stayed calm, listed the issues by severity, tackled the blockers first, and gave short regular updates to stakeholders. We launched on time, and I learned that structure and clear communication are the best antidotes to pressure.' WHERE question_text = 'Tell me about a time you had to work under significant pressure.';
UPDATE question_bank SET answer_text = 'I proposed trying an unproven approach to solve a recurring problem. I limited the risk with a small pilot, defined success criteria beforehand and had a fallback. The pilot worked, and we rolled it out more widely.' WHERE question_text = 'Give an example of a time you took a calculated risk.';
UPDATE question_bank SET answer_text = 'While reviewing routine data, I spotted a trend that suggested a growing issue no one had flagged. I verified it, summarized the evidence and raised it with the owner. Acting early let us fix it before customers were affected.' WHERE question_text = 'Describe a time you identified a problem before anyone else noticed it.';
UPDATE question_bank SET answer_text = 'I needed another team to prioritize something that did not report to me. I explained how it helped their goals, brought data, made the ask specific and small, and acknowledged their constraints. They agreed, and the work was completed that sprint.' WHERE question_text = 'Tell me about a time you had to influence people without formal authority.';
UPDATE question_bank SET answer_text = 'I missed a deadline because a dependency slipped and I had not flagged the risk early enough. As soon as I saw it, I told my manager, proposed a revised date, and delivered a partial result meanwhile. Since then I raise risks as soon as I see them.' WHERE question_text = 'Describe a time you missed a deadline. What happened and what did you do?';
UPDATE question_bank SET answer_text = 'We had to ship quickly, but one area was high-risk. I agreed with the team to cut scope in low-risk areas, keep thorough checks on the critical part, and schedule cleanup afterwards. This kept the date without compromising what mattered most.' WHERE question_text = 'Tell me about a time you had to balance quality with speed.';
UPDATE question_bank SET answer_text = 'When a cross-team initiative needed extra hands, I volunteered even though it was outside my role. It stretched my skills, built relationships across the company, and I brought lessons back that improved my own team''s process.' WHERE question_text = 'Describe a time you volunteered for something outside your usual responsibilities.';
UPDATE question_bank SET answer_text = 'After a miscommunication caused a stakeholder to lose confidence, I owned my part, met them to listen, and agreed on clearer update rhythms. By consistently delivering on small commitments, trust returned over a few weeks.' WHERE question_text = 'Tell me about a time you had to rebuild trust with a colleague or stakeholder.';
UPDATE question_bank SET answer_text = 'The toughest decision was deciding to stop a project that had significant effort invested but was no longer aligned with goals. I presented the evidence, acknowledged the team''s work, and redirected everyone to a higher-value effort. It was hard but it was the right call.' WHERE question_text = 'Describe the toughest decision you''ve had to make in your career so far.';

-- ===== SHARED QUESTIONS: CULTURE FIT =====
UPDATE question_bank SET answer_text = 'Tailor this to the company: mention a specific product, value or challenge that attracts you, and connect it to your skills. For example: "I admire how your team approaches X, and my experience with Y lets me contribute from day one."' WHERE question_text = 'Why do you want to work here specifically?';
UPDATE question_bank SET answer_text = 'I do my best work in collaborative environments with clear goals, autonomy on how to reach them, and open feedback. I like teams where people ask questions freely and share credit.' WHERE question_text = 'What kind of work environment brings out your best performance?';
UPDATE question_bank SET answer_text = 'Success means meeting the goals set for the role, building strong working relationships and leaving the team in a better position than I found it. I would confirm specific measures with my manager in the first weeks.' WHERE question_text = 'How do you define success in this role?';
UPDATE question_bank SET answer_text = 'I am looking for more scope, new challenges and a team that invests in growth. I have learned a lot in my current role, and I want to apply it somewhere I can have a larger impact.' WHERE question_text = 'What are you looking for in your next position that you don''t have now?';
UPDATE question_bank SET answer_text = 'I stay organized by clarifying the goal, breaking work into small steps and re-prioritizing as things change. I ask questions early, make reasonable assumptions explicit, and treat ambiguity as an opportunity to add structure.' WHERE question_text = 'How do you handle working in a fast-paced, ambiguous environment?';
UPDATE question_bank SET answer_text = 'Honesty, respect, ownership and continuous learning matter most to me. I want to work where people are open about problems and supportive in solving them.' WHERE question_text = 'What values matter most to you in a workplace?';
UPDATE question_bank SET answer_text = 'I prefer regular, specific and timely feedback, ideally with examples and suggestions. Short check-ins help me adjust early, and I welcome both positive and constructive input.' WHERE question_text = 'How do you prefer to receive feedback from managers?';
UPDATE question_bank SET answer_text = 'I am motivated by solving meaningful problems, learning new things and seeing the impact of my work on users or teammates. Working with talented, collaborative people also energizes me.' WHERE question_text = 'What motivates you to do your best work?';
UPDATE question_bank SET answer_text = 'I listen first, avoid assumptions, and ask people how they prefer to communicate. Different perspectives usually lead to better solutions, so I actively invite input from everyone.' WHERE question_text = 'How do you approach collaborating with people from different backgrounds?';
UPDATE question_bank SET answer_text = 'In three to five years I see myself having grown in expertise and responsibility, possibly leading larger projects or mentoring others, ideally within this company as I deliver value.' WHERE question_text = 'Where do you see yourself professionally in three to five years?';
UPDATE question_bank SET answer_text = 'A healthy team culture has psychological safety, clear roles, honest feedback and shared celebration of wins. People feel comfortable raising concerns and helping each other.' WHERE question_text = 'What does a healthy team culture look like to you?';
UPDATE question_bank SET answer_text = 'I connect routine tasks to the bigger goal, set small targets, and look for ways to automate or improve them. Finishing the foundational work well also makes the exciting work possible.' WHERE question_text = 'How do you stay motivated during repetitive or less exciting tasks?';
UPDATE question_bank SET answer_text = 'Research the company beforehand and name something real, such as its mission, a recent launch, or how it is changing the industry, and explain why it resonates with you personally.' WHERE question_text = 'What''s something about our company or industry that excites you?';
UPDATE question_bank SET answer_text = 'Constraints push creativity. I prioritize what has the highest impact, reuse existing tools, look for low-cost alternatives, and communicate clearly what is and is not feasible.' WHERE question_text = 'How do you handle working with limited resources or budget constraints?';
UPDATE question_bank SET answer_text = 'I thrive under managers who set clear expectations, trust me with autonomy, and are available for guidance and feedback when needed.' WHERE question_text = 'What kind of management style helps you thrive?';
UPDATE question_bank SET answer_text = 'I do focused independent work for deep tasks and sync with the team regularly to stay aligned, share progress and get input. I try to be both self-sufficient and a good collaborator.' WHERE question_text = 'How do you balance independent work with team collaboration?';
UPDATE question_bank SET answer_text = 'They would likely say I am reliable, communicative and willing to help, someone who follows through and stays calm under pressure. I would add that I am always working to improve.' WHERE question_text = 'What would your previous colleagues say about working with you?';
UPDATE question_bank SET answer_text = 'I learn the goals, tools and people first: reading documentation, meeting teammates, and asking questions. I look for an early small win to build credibility and confidence.' WHERE question_text = 'How do you approach onboarding into a new team or company?';
UPDATE question_bank SET answer_text = 'To me it means working effectively during working hours and protecting time to recharge outside them. I am flexible when something urgent arises, but I try to sustain a pace that avoids burnout.' WHERE question_text = 'What does work-life balance mean to you in practice?';
UPDATE question_bank SET answer_text = 'Stay positive and forward-looking: "I have learned a lot in my role, and I am looking for a bigger challenge and growth opportunities that this position offers." Avoid criticizing former employers.' WHERE question_text = 'Why are you leaving your current role, or why did you leave your last one?';

-- ===== SHARED QUESTIONS: COMMUNICATION =====
UPDATE question_bank SET answer_text = 'I start with the outcome that matters to them, use a simple analogy from everyday life, avoid jargon, and check understanding by asking them to summarize. I then add detail only as needed.' WHERE question_text = 'How would you explain a complex idea to someone with no background in it?';
UPDATE question_bank SET answer_text = 'I lead with the headline, then give status, risks and next steps in a few lines. I tailor detail to the audience, use a consistent format and flag anything needing a decision.' WHERE question_text = 'Describe your approach to writing clear, concise updates for stakeholders.';
UPDATE question_bank SET answer_text = 'I clarify quickly what each person understood, restate the shared goal, and agree on a written summary. Then I look for the cause, such as unclear ownership or channels, and fix the process.' WHERE question_text = 'How do you handle miscommunication within a team?';
UPDATE question_bank SET answer_text = 'I told a client a delivery would slip. I informed them promptly, explained the cause without excuses, presented a recovery plan and new date, and offered regular updates. They valued the honesty and stayed with us.' WHERE question_text = 'Tell me about a time you had to communicate bad news to a client or stakeholder.';
UPDATE question_bank SET answer_text = 'I consider what each audience cares about: executives want outcomes and risks, engineers want detail, customers want clarity and benefits. I adjust vocabulary, length and format, and check how it lands.' WHERE question_text = 'How do you tailor your communication style for different audiences?';
UPDATE question_bank SET answer_text = 'I use shared written updates, clear documentation, regular check-ins and an agreed channel for urgent items. I make decisions visible and record meeting notes so nobody is left out across time zones.' WHERE question_text = 'Describe how you keep remote or distributed teammates informed.';
UPDATE question_bank SET answer_text = 'I ask the other person to paraphrase, invite questions, and follow up in writing with the key points and actions. If something seems unclear, I rephrase.' WHERE question_text = 'How do you make sure your message is understood, not just delivered?';
UPDATE question_bank SET answer_text = 'In a tense conversation, I focused on listening and reflected back what I heard. It revealed that the real concern was different from the stated one, which let us agree on a solution quickly.' WHERE question_text = 'Tell me about a time active listening changed the outcome of a conversation.';
UPDATE question_bank SET answer_text = 'Tone is easy to misread in text, so I assume good intent, keep messages factual, and move to a call when it escalates. Afterwards I summarize the agreement in writing.' WHERE question_text = 'How do you handle disagreements that happen over email or chat rather than in person?';
UPDATE question_bank SET answer_text = 'I make sure there is an agenda and a clear purpose, come prepared, keep to time, encourage quieter voices, and end with decisions, owners and dates.' WHERE question_text = 'Describe your approach to running or contributing to a meeting effectively.';
UPDATE question_bank SET answer_text = 'I ask specific questions, restate my understanding, and propose an assumption to confirm, such as "I understand the goal is X; is that right?" This is quicker and clearer than a vague request.' WHERE question_text = 'How do you ask for clarification when instructions are unclear?';
UPDATE question_bank SET answer_text = 'After leadership made a decision I disagreed with, I voiced my concerns in the right forum beforehand. Once decided, I communicated it to my team clearly, explained the reasoning and supported it professionally.' WHERE question_text = 'Tell me about a time you had to communicate a decision you personally disagreed with.';
UPDATE question_bank SET answer_text = 'I write short, structured docs covering context, decisions, how to run things and known issues, store them where the team looks, and update them as things change. I ask a colleague to test them.' WHERE question_text = 'How do you document your work so others can pick it up easily?';
UPDATE question_bank SET answer_text = 'In a meeting a colleague said they were fine with the plan, but their body language suggested hesitation. I checked in privately, learned of a real concern, and we addressed it before it caused problems.' WHERE question_text = 'Describe a time nonverbal cues told you more than someone''s words did.';
UPDATE question_bank SET answer_text = 'I give feedback privately, soon after the event, focus on specific behavior and its impact, and ask for their view. I also acknowledge strengths and offer help, so it feels supportive.' WHERE question_text = 'How do you give constructive feedback without damaging a working relationship?';

-- ===== SHARED QUESTIONS: BACKGROUND =====
UPDATE question_bank SET answer_text = 'Give a concise two-minute chronology: where you started, key roles and achievements, what you learned at each step, and how it leads logically to this role. End with why you are excited about this opportunity.' WHERE question_text = 'Walk me through your resume and career path so far.';
UPDATE question_bank SET answer_text = 'Share a genuine origin: a curiosity, project or person that sparked your interest, and how it grew into a career. Show enduring passion, not just a paycheck.' WHERE question_text = 'What drew you to this field initially?';
UPDATE question_bank SET answer_text = 'Choose an achievement with measurable impact, describe your specific contribution and the obstacles overcome, and say what it taught you.' WHERE question_text = 'What accomplishment from your career are you most proud of?';
UPDATE question_bank SET answer_text = 'Highlight two or three strengths that match the job: for example deep expertise in a key area, a record of delivering results, and strong collaboration. Support each with a brief example.' WHERE question_text = 'What skills do you bring that set you apart from other candidates?';
UPDATE question_bank SET answer_text = 'Pick a real moment, such as a new role, a failure or a mentor''s advice, that changed your direction or approach, and explain what changed in how you work afterwards.' WHERE question_text = 'What has been the biggest turning point in your career?';
UPDATE question_bank SET answer_text = 'Connect two or three past responsibilities and results directly to the job description, showing you have done similar work and are ready for the next level.' WHERE question_text = 'How has your previous experience prepared you for this role?';
UPDATE question_bank SET answer_text = 'Name a specific skill, the way you learned it (course, project, mentor), and how you have already applied it at work. This shows initiative and continuous learning.' WHERE question_text = 'What''s a skill you''ve developed recently, and how did you go about it?';
UPDATE question_bank SET answer_text = 'Describe a mentor or experience, such as a manager who taught me to give clear feedback, and how that still shapes how I plan, communicate and help others.' WHERE question_text = 'Describe a mentor or experience that shaped how you work today.';
UPDATE question_bank SET answer_text = 'The most valuable lesson was the importance of communicating early and often. Many problems are small when raised promptly, and trust with colleagues grows from consistency.' WHERE question_text = 'What was the most valuable lesson from your last job?';
UPDATE question_bank SET answer_text = 'I follow industry blogs and newsletters, take courses, join communities, try new tools in small side projects, and share what I learn with colleagues.' WHERE question_text = 'How do you keep your skills current in a changing field?';
UPDATE question_bank SET answer_text = 'Projects that combine a real problem, cross-functional collaboration and measurable impact energize me, especially where I can learn something new while delivering value.' WHERE question_text = 'What type of projects energize you the most?';
UPDATE question_bank SET answer_text = 'Be honest and constructive: name one genuine gap, such as limited exposure to a specific tool, and explain the steps you are taking to close it, such as a course or a side project.' WHERE question_text = 'What gaps do you see in your experience, and how are you addressing them?';
UPDATE question_bank SET answer_text = 'I once took a role that turned out to be a poor fit. I identified why, learned what matters to me in a job, and used it to choose my next role more carefully. It made my career direction clearer.' WHERE question_text = 'Tell me about a career decision that didn''t go as planned.';
UPDATE question_bank SET answer_text = 'I hope to grow in technical or functional depth and take on more responsibility, such as leading projects and mentoring others, in ways that benefit the team and company.' WHERE question_text = 'What are you hoping to grow into over the next few years?';
UPDATE question_bank SET answer_text = 'Because my experience and skills match what you need, I have a track record of delivering results, and I am motivated by this company''s mission. I can contribute quickly and keep growing with the team.' WHERE question_text = 'Why should we hire you for this specific position?';

-- ===== SOFTWARE ENGINEER: TECHNICAL =====
UPDATE question_bank SET answer_text = 'An abstract class can hold state and partial implementations and a class can extend only one, while an interface defines a contract that many classes can implement. Use an abstract class for shared base behavior and an interface for capabilities that unrelated types can share.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain the difference between an abstract class and an interface.';
UPDATE question_bank SET answer_text = 'Big-O describes how an algorithm''s time or space grows with input size, ignoring constants. It matters because it predicts whether code will still perform when data grows, for example O(n log n) sorting versus O(n^2).' WHERE job_role = 'Software Engineer' AND question_text = 'What is Big-O notation and why does it matter?';
UPDATE question_bank SET answer_text = 'Monitor memory over time, take heap snapshots or profiles at intervals, and compare to find objects that keep growing. Trace the retaining references (often unremoved listeners, caches or globals), fix the lifecycle, and verify with a load test.' WHERE job_role = 'Software Engineer' AND question_text = 'How would you detect and fix a memory leak in a long-running application?';
UPDATE question_bank SET answer_text = 'A hash table maps keys to array slots using a hash function, with collisions handled by chaining or open addressing. Average lookup is O(1), worst case O(n) if many keys collide.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain how a hash table works and its average time complexity for lookups.';
UPDATE question_bank SET answer_text = 'SQL databases have fixed schemas, joins and strong ACID guarantees, which suit relational, transactional data. NoSQL stores (document, key-value, wide-column, graph) offer flexible schemas and easier horizontal scaling, which suit large, varied or high-throughput workloads.' WHERE job_role = 'Software Engineer' AND question_text = 'What is the difference between SQL and NoSQL databases, and when would you choose each?';
UPDATE question_bank SET answer_text = 'An index is a data structure (often a B-tree) that speeds up reads on chosen columns. The trade-off is extra storage and slower writes, since indexes must be updated, so index columns used in filters, joins and sorts.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain the concept of database indexing and its trade-offs.';
UPDATE question_bank SET answer_text = 'Model resources as nouns with clear URLs, use HTTP methods and status codes correctly, keep it stateless, support pagination and filtering, version the API, secure it, return consistent errors and document it with OpenAPI.' WHERE job_role = 'Software Engineer' AND question_text = 'How do you approach designing a RESTful API?';
UPDATE question_bank SET answer_text = 'Synchronous code blocks until each operation finishes, while asynchronous code starts an operation and continues, handling the result later via callbacks, promises or async/await. Async improves throughput for I/O-bound work.' WHERE job_role = 'Software Engineer' AND question_text = 'What is the difference between synchronous and asynchronous code execution?';
UPDATE question_bank SET answer_text = 'Garbage collectors find objects no longer reachable from roots and reclaim their memory, often using generational collection (young versus old objects) with mark-and-sweep or copying. Tuning focuses on reducing pause times and allocation pressure.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain how garbage collection works in your primary programming language.';
UPDATE question_bank SET answer_text = 'A race condition occurs when the outcome depends on the timing of concurrent operations on shared state. Prevent it with locks, atomic operations, immutable data, message passing or database transactions.' WHERE job_role = 'Software Engineer' AND question_text = 'What is a race condition, and how would you prevent one?';
UPDATE question_bank SET answer_text = 'A process has its own memory space and is isolated; threads within a process share memory and are lighter weight. Threads communicate easily but need synchronization, while processes need IPC but give better isolation.' WHERE job_role = 'Software Engineer' AND question_text = 'Describe the differences between processes and threads.';
UPDATE question_bank SET answer_text = 'Generate a short unique key (base62 of an auto-increment ID or a random/hashed value), store key to URL in a database, cache hot links, and return a 301/302 redirect. Add rate limiting, analytics, expiry and horizontal scaling with a load balancer.' WHERE job_role = 'Software Engineer' AND question_text = 'How would you design a URL shortening service?';
UPDATE question_bank SET answer_text = 'CAP says a distributed system under a network partition must choose between consistency and availability. CP systems reject some requests to stay consistent; AP systems stay available but may return stale data.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain the CAP theorem and its implications for distributed systems.';
UPDATE question_bank SET answer_text = 'Dependency injection supplies a class''s dependencies from outside instead of creating them internally. It reduces coupling, makes code easier to test with mocks and allows swapping implementations.' WHERE job_role = 'Software Engineer' AND question_text = 'What is dependency injection and why is it useful?';
UPDATE question_bank SET answer_text = 'I write tests for expected behavior, edge cases and failures, keep them small and independent, mock external dependencies and make them readable. Often I write tests alongside or before code, and run them in CI.' WHERE job_role = 'Software Engineer' AND question_text = 'How do you approach writing unit tests for a new feature?';
UPDATE question_bank SET answer_text = 'Unit tests check small pieces in isolation and are fast; integration tests check that components work together, such as with a database; end-to-end tests exercise the whole system through the user path and are slower and more brittle. Use many unit tests and fewer end-to-end tests.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain the difference between unit, integration, and end-to-end tests.';
UPDATE question_bank SET answer_text = 'SOLID: Single responsibility, Open/closed, Liskov substitution, Interface segregation, Dependency inversion. Together they promote modular, maintainable code that is easier to extend and test.' WHERE job_role = 'Software Engineer' AND question_text = 'What are the SOLID principles and why do they matter?';
UPDATE question_bank SET answer_text = 'Look at the execution plan, add or fix indexes, select only needed columns, avoid functions on indexed columns, reduce joins or rewrite subqueries, and consider caching or partitioning. Measure before and after.' WHERE job_role = 'Software Engineer' AND question_text = 'How would you optimize a slow-running SQL query?';
UPDATE question_bank SET answer_text = 'REST exposes multiple endpoints returning fixed structures; GraphQL has a single endpoint where clients request exactly the fields they need. GraphQL reduces over- and under-fetching but adds complexity in caching and query cost control.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain the difference between REST and GraphQL.';
UPDATE question_bank SET answer_text = 'A deadlock is when two or more processes wait forever for each other''s resources. Avoid it by acquiring locks in a consistent order, using timeouts, minimizing lock scope, or using lock-free structures.' WHERE job_role = 'Software Engineer' AND question_text = 'What is a deadlock, and how can it be avoided?';
UPDATE question_bank SET answer_text = 'Use an algorithm such as token bucket or sliding window, keyed by user or IP, with counters stored in a fast shared store like Redis. Return HTTP 429 with a retry header and make it work across multiple servers.' WHERE job_role = 'Software Engineer' AND question_text = 'Describe how you would design a rate limiter.';
UPDATE question_bank SET answer_text = 'Vertical scaling adds more power (CPU, RAM) to one machine; horizontal scaling adds more machines. Horizontal scales further and improves resilience but requires distributed design.' WHERE job_role = 'Software Engineer' AND question_text = 'What is the difference between horizontal and vertical scaling?';
UPDATE question_bank SET answer_text = 'Caching stores frequently used data in faster storage to cut latency and load. Apply it at the browser, CDN, application and database layers, with an eviction policy and an invalidation strategy.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain how caching works and where you''d apply it in a system.';
UPDATE question_bank SET answer_text = 'Microservices split an application into small independently deployable services, offering team autonomy and independent scaling. Trade-offs include network complexity, distributed data, harder debugging and operational overhead compared with a simpler monolith.' WHERE job_role = 'Software Engineer' AND question_text = 'What are microservices, and what trade-offs come with them versus a monolith?';
UPDATE question_bank SET answer_text = 'Use HTTPS, strong authentication (OAuth2/JWT), authorization checks, input validation, rate limiting, secrets management, logging and monitoring, and follow the OWASP API Top 10.' WHERE job_role = 'Software Engineer' AND question_text = 'How would you secure a public-facing API?';
UPDATE question_bank SET answer_text = 'Authentication verifies who you are; authorization determines what you are allowed to do. Login is authentication, role-based access is authorization.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain the difference between authentication and authorization.';
UPDATE question_bank SET answer_text = 'An idempotent operation gives the same result no matter how many times it is applied. It matters because clients retry on failures; for example PUT and DELETE are idempotent, and payments use idempotency keys to avoid double charges.' WHERE job_role = 'Software Engineer' AND question_text = 'What is idempotency, and why does it matter for API design?';
UPDATE question_bank SET answer_text = 'Common approaches are URL versioning (/v1/), header versioning or media types. I favor additive, backward-compatible changes, clear deprecation policies and long enough overlap for clients to migrate.' WHERE job_role = 'Software Engineer' AND question_text = 'How do you handle versioning in an API?';
UPDATE question_bank SET answer_text = 'A load balancer distributes incoming requests across servers using algorithms such as round-robin or least connections, performs health checks to avoid failed nodes, and improves availability and scalability.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain how a load balancer works.';
UPDATE question_bank SET answer_text = 'Eventual consistency means replicas converge to the same value if no new updates occur, though reads may be briefly stale. It is acceptable for things like social feeds, likes or analytics, but not for balances or inventory that need strong consistency.' WHERE job_role = 'Software Engineer' AND question_text = 'What is eventual consistency, and when is it acceptable?';
UPDATE question_bank SET answer_text = 'I check correctness, readability, tests, edge cases, security and performance, and consistency with the codebase. I give specific, kind and actionable comments, and distinguish blocking issues from suggestions.' WHERE job_role = 'Software Engineer' AND question_text = 'Describe your approach to code review and what you look for.';
UPDATE question_bank SET answer_text = 'Refactor when the structure is mostly sound and tests exist, improving incrementally. Rewrite only when the design is fundamentally unfixable and the cost of continuing exceeds a rewrite, since rewrites carry large risk.' WHERE job_role = 'Software Engineer' AND question_text = 'How do you decide when to refactor versus rewrite code?';
UPDATE question_bank SET answer_text = 'A data pipeline moves data from sources to storage and consumers; ETL is Extract, Transform, Load: pull raw data, clean and reshape it, and load it into a warehouse. Key concerns are reliability, scalability, data quality and monitoring.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain the concept of Big Data pipelines and ETL.';
UPDATE question_bank SET answer_text = 'CI automatically builds and tests every change; CD automatically releases passing builds. They catch bugs early, reduce risky big-bang releases and speed up feedback and delivery.' WHERE job_role = 'Software Engineer' AND question_text = 'What is continuous integration/continuous deployment (CI/CD), and why is it valuable?';
UPDATE question_bank SET answer_text = 'Use stateless services behind load balancers with autoscaling, caching, CDNs, database replication and sharding, async processing with queues, rate limiting and strong monitoring. Design for failure and test with load tests.' WHERE job_role = 'Software Engineer' AND question_text = 'How would you design a system to handle millions of concurrent users?';
UPDATE question_bank SET answer_text = 'Optimistic locking assumes conflicts are rare, checking a version at commit and retrying if it changed. Pessimistic locking locks the data up front to prevent conflicts. Optimistic suits low contention; pessimistic suits high contention.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain the difference between optimistic and pessimistic locking.';
UPDATE question_bank SET answer_text = 'A message queue holds messages between producers and consumers, decoupling them. Use it for asynchronous tasks, load smoothing, retries and event-driven workflows, such as sending emails or processing orders.' WHERE job_role = 'Software Engineer' AND question_text = 'What is a message queue, and when would you use one?';
UPDATE question_bank SET answer_text = 'Reproduce if possible, review metrics and recent changes, add targeted logging or tracing, form hypotheses and test them, and use sampling or feature flags in production. Afterwards, improve observability.' WHERE job_role = 'Software Engineer' AND question_text = 'How do you approach debugging a production issue with limited logs?';
UPDATE question_bank SET answer_text = 'Stateful services keep client session data between requests; stateless ones do not, so any instance can handle any request. Stateless services scale and recover more easily, with state held in external stores.' WHERE job_role = 'Software Engineer' AND question_text = 'Explain the difference between stateful and stateless services.';
UPDATE question_bank SET answer_text = 'Technical debt is the future cost of shortcuts taken in code or design. Manage it by tracking it visibly, allocating regular capacity to pay it down, prioritizing by impact and preventing new debt through reviews and standards.' WHERE job_role = 'Software Engineer' AND question_text = 'What is technical debt, and how do you manage it on a team?';

-- ===== SOFTWARE ENGINEER: SITUATIONAL =====
UPDATE question_bank SET answer_text = 'Assess severity and impact, tell the release owner and stakeholders immediately, and recommend whether to delay or fix first. Fix and test properly or roll back, and hold a short post-mortem to improve checks.' WHERE job_role = 'Software Engineer' AND question_text = 'You discover a critical bug in production right before a major release. What do you do?';
UPDATE question_bank SET answer_text = 'Assume good intent, separate tone from content, and address the technical points. If the pattern continues, I would talk privately and ask for more constructive framing, escalating only if needed.' WHERE job_role = 'Software Engineer' AND question_text = 'A teammate''s code review comments seem overly harsh. How do you respond?';
UPDATE question_bank SET answer_text = 'Clarify the requirement, discuss options with the team such as adapting the architecture, an adapter layer or a phased approach, and weigh cost versus risk. Document the decision and avoid hacks that create lasting debt.' WHERE job_role = 'Software Engineer' AND question_text = 'You''re asked to add a feature that conflicts with existing architecture. How do you proceed?';
UPDATE question_bank SET answer_text = 'Tell the stakeholders as soon as I know, explain the cause, give a revised estimate with confidence range, and offer options such as reducing scope. I then learn from the miss to improve future estimates.' WHERE job_role = 'Software Engineer' AND question_text = 'Your estimate for a task turns out to be way off. How do you communicate that?';
UPDATE question_bank SET answer_text = 'Get it running, read entry points and trace key flows, write characterization tests, talk to people who know the history, and document as I learn. Refactor in small, safe steps.' WHERE job_role = 'Software Engineer' AND question_text = 'You inherit a legacy codebase with no documentation. Where do you start?';
UPDATE question_bank SET answer_text = 'Understand the business pressure, explain the specific risks, and offer options such as a smaller scope, a phased rollout or feature flags. Document the agreed decision and risks.' WHERE job_role = 'Software Engineer' AND question_text = 'A stakeholder wants a feature shipped faster than you believe is safe. What do you do?';
UPDATE question_bank SET answer_text = 'Report it promptly to the responsible owner or security team through the proper channel, avoid exposing details widely, and offer to help fix it. Track it until resolved.' WHERE job_role = 'Software Engineer' AND question_text = 'You notice a security vulnerability that isn''t part of your assigned task. What''s your next step?';
UPDATE question_bank SET answer_text = 'Have each explain their approach, focus on shared goals and criteria such as performance, maintainability and timeline, and suggest a small prototype or data if needed. If still stuck, involve the tech lead to decide.' WHERE job_role = 'Software Engineer' AND question_text = 'Two team members disagree strongly on a technical approach. How do you help resolve it?';
UPDATE question_bank SET answer_text = 'Agree on the contract, build against a mock or stub, work on other tasks meanwhile, and follow up with the other team, escalating if needed. Communicate the dependency risk to my lead.' WHERE job_role = 'Software Engineer' AND question_text = 'You''re blocked waiting on another team''s API. How do you keep moving?';
UPDATE question_bank SET answer_text = 'Reproduce the customer''s exact scenario, check whether the tests cover that path, compare environments and data, and review recent changes and logs. Then fix the bug and add a regression test.' WHERE job_role = 'Software Engineer' AND question_text = 'Your automated tests pass, but a customer reports a bug in that exact area. What do you investigate first?';
UPDATE question_bank SET answer_text = 'Learn the core concepts quickly from official docs, build a small spike to reduce risk, ask experienced colleagues, flag risks to the team and keep the first implementation simple.' WHERE job_role = 'Software Engineer' AND question_text = 'You''re asked to use a new technology you''ve never worked with under a tight deadline. How do you approach it?';
UPDATE question_bank SET answer_text = 'Acknowledge the alert, assess impact, communicate in the incident channel, mitigate first (rollback or failover), then find root cause. Keep stakeholders updated and write a blameless post-mortem.' WHERE job_role = 'Software Engineer' AND question_text = 'A production outage occurs at 2 a.m. Walk me through how you''d handle it.';
UPDATE question_bank SET answer_text = 'Stop and confirm the issue, tell the team and product owner quickly, propose a revised plan or scope, and update the sprint plan transparently. Capture the learning for planning.' WHERE job_role = 'Software Engineer' AND question_text = 'You realize partway through a sprint that the original plan won''t work. What do you do?';
UPDATE question_bank SET answer_text = 'Understand the pressure, explain the risks of the shortcuts, and propose alternatives such as reducing scope while keeping quality for critical parts. If a shortcut is agreed, document it and plan the follow-up.' WHERE job_role = 'Software Engineer' AND question_text = 'Your manager asks you to cut corners to meet a deadline. How do you respond?';
UPDATE question_bank SET answer_text = 'Document the system, pair with others, run knowledge-sharing sessions, add tests and diagrams, and rotate responsibilities so the knowledge is spread.' WHERE job_role = 'Software Engineer' AND question_text = 'You''re the only person who understands a critical piece of the system. How do you address that risk?';
UPDATE question_bank SET answer_text = 'Acknowledge it works, explain the reasons behind the best practices with examples, suggest specific improvements and offer to pair. Keep feedback encouraging and educational.' WHERE job_role = 'Software Engineer' AND question_text = 'A junior developer submits code that works but violates best practices. How do you handle the review?';
UPDATE question_bank SET answer_text = 'Define criteria such as cost, performance, maintainability and risk, compare options with a quick prototype if needed, consult the team, choose the more reversible option and document the decision.' WHERE job_role = 'Software Engineer' AND question_text = 'You have to choose between two competing technical solutions with no clear best answer. How do you decide?';
UPDATE question_bank SET answer_text = 'Identify why we are behind, reprioritize to the minimum viable scope, remove blockers, communicate honestly with stakeholders, and avoid unsustainable overtime.' WHERE job_role = 'Software Engineer' AND question_text = 'Your team is falling behind on a project with a hard deadline. What steps do you take?';
UPDATE question_bank SET answer_text = 'Assess whether we are affected and how severely, upgrade or patch to a fixed version, or apply a mitigation, test, deploy and inform the security team. Add dependency scanning to prevent surprises.' WHERE job_role = 'Software Engineer' AND question_text = 'You find that a dependency you rely on has a critical vulnerability. What do you do?';
UPDATE question_bank SET answer_text = 'Agree on a change process: requirements locked per sprint, new requests go to the backlog and are prioritized. Explain the cost of mid-sprint changes in plain terms and meet regularly.' WHERE job_role = 'Software Engineer' AND question_text = 'A non-technical stakeholder keeps changing requirements mid-sprint. How do you manage it?';
UPDATE question_bank SET answer_text = 'Focus on the code, frame feedback respectfully as questions or suggestions with reasons, and bring evidence. If we still disagree, discuss in person or involve the team lead.' WHERE job_role = 'Software Engineer' AND question_text = 'You''re asked to review a pull request from someone senior to you and disagree with their approach. How do you proceed?';
UPDATE question_bank SET answer_text = 'Gather logs and failure patterns, look for common factors such as time, agent or step, check for flaky tests, resource limits or external dependencies, and reproduce. Add retries or isolation as a stopgap and fix the root cause.' WHERE job_role = 'Software Engineer' AND question_text = 'Your deployment pipeline fails intermittently. How would you troubleshoot it?';
UPDATE question_bank SET answer_text = 'Own it, tell the team promptly, assess the impact and fix or mitigate it. Then explain what I learned and how to prevent it, such as better tests or review.' WHERE job_role = 'Software Engineer' AND question_text = 'You discover that a previous decision you made caused a downstream problem. How do you handle it?';
UPDATE question_bank SET answer_text = 'Use an expand-and-contract approach: replicate to the new database, dual-write or use change data capture, verify data, gradually shift reads then writes, keep rollback ready and run rehearsals first.' WHERE job_role = 'Software Engineer' AND question_text = 'You need to migrate a production database with zero downtime. How would you plan it?';
UPDATE question_bank SET answer_text = 'Profile the feature and compare against a baseline, use metrics and traces to find the actual bottleneck, and check whether the regression correlates with my change. Be open about findings and fix it if it is mine.' WHERE job_role = 'Software Engineer' AND question_text = 'A feature you built is being blamed for a performance regression. How do you investigate?';
UPDATE question_bank SET answer_text = 'Be transparent with my manager, schedule fixed time for mentoring, such as short pairing sessions, and teach in ways that build independence. Adjust my plan if workload gets too heavy.' WHERE job_role = 'Software Engineer' AND question_text = 'You''re asked to mentor a struggling teammate while also meeting your own deadlines. How do you balance both?';
UPDATE question_bank SET answer_text = 'Raise concerns with specifics such as risks, migration cost and fit, in a design discussion or proposal. Offer to help evaluate through a small proof of concept, and commit once the team decides.' WHERE job_role = 'Software Engineer' AND question_text = 'Your team wants to adopt a new framework, but you have concerns. How do you voice them?';
UPDATE question_bank SET answer_text = 'Read what exists, explore with a sandbox and write tests that capture actual behavior, wrap the API in an adapter to isolate its quirks, and contact the vendor with specific questions.' WHERE job_role = 'Software Engineer' AND question_text = 'You have to work with an external vendor''s poorly documented API. How do you approach integration?';
UPDATE question_bank SET answer_text = 'Acknowledge the impact, redistribute work, capture their knowledge through handover, reprioritize scope if needed and keep morale up with clear communication.' WHERE job_role = 'Software Engineer' AND question_text = 'A key team member leaves mid-project. How do you help the team adjust?';
UPDATE question_bank SET answer_text = 'Break the project into pieces, list assumptions and unknowns, estimate ranges, add contingency, spike on the riskiest unknowns, and commit to updating the estimate as we learn.' WHERE job_role = 'Software Engineer' AND question_text = 'You''re asked to estimate a project with many unknowns. How do you approach the estimate?';

-- ===== DATA SCIENTIST: TECHNICAL =====
UPDATE question_bank SET answer_text = 'Bias is error from overly simple assumptions (underfitting); variance is sensitivity to training noise (overfitting). More model complexity lowers bias but raises variance, so the goal is the sweet spot with the lowest total error, found through validation.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the bias-variance tradeoff.';
UPDATE question_bank SET answer_text = 'Overfitting is when a model learns noise in training data and performs poorly on new data. Prevent it with more data, simpler models, regularization, cross-validation, early stopping, dropout and feature selection.' WHERE job_role = 'Data Scientist' AND question_text = 'What is overfitting, and how do you prevent it?';
UPDATE question_bank SET answer_text = 'Supervised learning uses labeled data to predict outcomes (classification, regression). Unsupervised learning finds structure in unlabeled data, such as clusters or lower-dimensional representations.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the difference between supervised and unsupervised learning.';
UPDATE question_bank SET answer_text = 'Cross-validation splits data into folds, training on some and validating on the rest, rotating through all. It gives a more reliable estimate of generalization performance and helps tune hyperparameters without wasting data.' WHERE job_role = 'Data Scientist' AND question_text = 'What is cross-validation, and why is it important?';
UPDATE question_bank SET answer_text = 'Precision is the share of predicted positives that are correct; recall is the share of actual positives found; F1 is their harmonic mean. Prioritize precision when false positives are costly (spam filtering) and recall when misses are costly (disease screening).' WHERE job_role = 'Data Scientist' AND question_text = 'Explain precision, recall, and F1 score, and when each matters most.';
UPDATE question_bank SET answer_text = 'Regularization penalizes model complexity to reduce overfitting. L1 (lasso) adds absolute weights and drives some to zero, giving sparsity; L2 (ridge) adds squared weights and shrinks them smoothly.' WHERE job_role = 'Data Scientist' AND question_text = 'What is regularization, and how do L1 and L2 differ?';
UPDATE question_bank SET answer_text = 'Bagging trains models in parallel on bootstrapped samples and averages them to reduce variance (random forest). Boosting trains models sequentially, each correcting the previous errors, to reduce bias (gradient boosting).' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the difference between bagging and boosting.';
UPDATE question_bank SET answer_text = 'A random forest builds many decision trees on bootstrapped samples with random feature subsets at each split, and averages (or votes) their predictions. This reduces variance and overfitting compared to a single tree.' WHERE job_role = 'Data Scientist' AND question_text = 'How does a random forest model work?';
UPDATE question_bank SET answer_text = 'Gradient descent iteratively updates parameters in the direction that reduces the loss. A learning rate too high overshoots or diverges; too low is slow or gets stuck. Schedules and adaptive optimizers help.' WHERE job_role = 'Data Scientist' AND question_text = 'What is gradient descent, and how does learning rate affect it?';
UPDATE question_bank SET answer_text = 'Linearity of the relationship, independence of errors, homoscedasticity (constant error variance), normally distributed residuals and no severe multicollinearity.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the assumptions behind linear regression.';
UPDATE question_bank SET answer_text = 'Multicollinearity is when predictors are highly correlated, making coefficients unstable. Detect it with correlation matrices and variance inflation factor (VIF); address it by removing or combining variables, PCA or regularization.' WHERE job_role = 'Data Scientist' AND question_text = 'What is multicollinearity, and how do you detect and address it?';
UPDATE question_bank SET answer_text = 'A Type I error is a false positive: rejecting a true null hypothesis. A Type II error is a false negative: failing to reject a false null hypothesis. Lowering one generally raises the other.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the difference between a Type I and Type II error.';
UPDATE question_bank SET answer_text = 'First understand why data is missing (random or not), then choose: drop rows or columns if few, impute with mean, median or model-based methods, or add a missing indicator. Always avoid leakage by fitting imputers on training data only.' WHERE job_role = 'Data Scientist' AND question_text = 'How would you handle missing data in a dataset?';
UPDATE question_bank SET answer_text = 'Feature engineering creates informative inputs from raw data. Example: from a timestamp, derive hour of day, weekday and is_weekend, which can capture demand patterns the raw timestamp hides.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the concept of feature engineering and give an example.';
UPDATE question_bank SET answer_text = 'As the number of features grows, data becomes sparse and distances lose meaning, so models need exponentially more data and overfit more easily. Remedies include feature selection, dimensionality reduction and regularization.' WHERE job_role = 'Data Scientist' AND question_text = 'What is the curse of dimensionality?';
UPDATE question_bank SET answer_text = 'Avoid plain accuracy. Use precision, recall, F1, PR-AUC or ROC-AUC, and resample or use class weights. Evaluate with stratified splits and choose thresholds based on business costs.' WHERE job_role = 'Data Scientist' AND question_text = 'How do you evaluate a classification model when classes are imbalanced?';
UPDATE question_bank SET answer_text = 'A tree tests each candidate split and picks the one giving the largest impurity reduction, measured by Gini impurity or information gain (entropy) for classification, or variance reduction for regression.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain how a decision tree decides where to split.';
UPDATE question_bank SET answer_text = 'An A/B test compares a control and a variant on randomly assigned users. Define the metric and sample size beforehand, run the test, and use a hypothesis test; significance means the p-value is below the chosen alpha (e.g. 0.05), alongside effect size and confidence intervals.' WHERE job_role = 'Data Scientist' AND question_text = 'What is A/B testing, and how do you determine statistical significance?';
UPDATE question_bank SET answer_text = 'Correlation means two variables move together; causation means one produces a change in the other. Confounders, reverse causality or coincidence can create correlation without causation, so randomized experiments or causal methods are needed.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the difference between correlation and causation.';
UPDATE question_bank SET answer_text = 'A p-value is the probability of seeing results at least as extreme as observed if the null hypothesis were true. A small p-value is evidence against the null, but it is not the probability that the null is true and says nothing about effect size.' WHERE job_role = 'Data Scientist' AND question_text = 'What is a p-value, and how do you interpret one?';
UPDATE question_bank SET answer_text = 'Detect with visualizations, z-scores or the IQR rule, or model-based methods. Investigate whether they are errors or real; then keep, cap (winsorize), transform or remove them, and document the choice.' WHERE job_role = 'Data Scientist' AND question_text = 'How would you detect and handle outliers in a dataset?';
UPDATE question_bank SET answer_text = 'A network makes predictions in a forward pass, computes the loss, then backpropagation uses the chain rule to compute gradients of the loss with respect to each weight, and an optimizer updates the weights. Repeating this over data reduces the loss.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain how a neural network learns through backpropagation.';
UPDATE question_bank SET answer_text = 'Batch gradient descent uses the full dataset for each update: stable but slow. Stochastic uses one sample: fast and noisy. Mini-batch is the practical middle ground.' WHERE job_role = 'Data Scientist' AND question_text = 'What is the difference between batch and stochastic gradient descent?';
UPDATE question_bank SET answer_text = 'A confusion matrix tabulates true positives, false positives, true negatives and false negatives, from which accuracy, precision, recall and specificity are derived. It shows exactly what types of errors a classifier makes.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the concept of a confusion matrix.';
UPDATE question_bank SET answer_text = 'Start from the business objective and the cost of each error type. For example use recall for fraud detection, precision for costly interventions, RMSE or MAE for forecasts, and tie it to a business KPI.' WHERE job_role = 'Data Scientist' AND question_text = 'How do you choose the right evaluation metric for a business problem?';
UPDATE question_bank SET answer_text = 'Dimensionality reduction compresses features while keeping most information. PCA projects data onto orthogonal directions of maximum variance; use it to reduce noise and multicollinearity, speed training or visualize data.' WHERE job_role = 'Data Scientist' AND question_text = 'What is dimensionality reduction, and when would you use PCA?';
UPDATE question_bank SET answer_text = 'Parametric models assume a fixed functional form with a finite number of parameters (linear regression). Non-parametric models make fewer assumptions and grow in complexity with data (k-NN, decision trees) but need more data.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the difference between parametric and non-parametric models.';
UPDATE question_bank SET answer_text = 'Define a hypothesis and primary metric, choose randomization units, calculate sample size and duration, set guardrail metrics, run the test without peeking, analyze with the appropriate test and report effect size and uncertainty.' WHERE job_role = 'Data Scientist' AND question_text = 'How would you design an experiment to test a new product feature?';
UPDATE question_bank SET answer_text = 'Data leakage is when training uses information unavailable at prediction time, inflating results. Prevent it by splitting before preprocessing, using time-based splits for temporal data, using pipelines, and removing target-derived features.' WHERE job_role = 'Data Scientist' AND question_text = 'What is data leakage, and how do you prevent it?';
UPDATE question_bank SET answer_text = 'Start with a baseline such as popularity, then build collaborative filtering (user-item interactions or matrix factorization) and content-based features, combine into a hybrid, handle cold start, evaluate offline with ranking metrics and online with A/B tests.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain how you would build a recommendation system from scratch.';
UPDATE question_bank SET answer_text = 'A data warehouse stores structured, cleaned data with a schema for analytics and BI. A data lake stores raw data of any format cheaply with schema applied on read, suiting data science and big data.' WHERE job_role = 'Data Scientist' AND question_text = 'What is the difference between a data warehouse and a data lake?';
UPDATE question_bank SET answer_text = 'Remove irrelevant or redundant features with filters (correlation, mutual information), then use wrapper or embedded methods (L1, tree importances, recursive elimination), plus domain knowledge, validated through cross-validation.' WHERE job_role = 'Data Scientist' AND question_text = 'How do you approach feature selection when you have hundreds of variables?';
UPDATE question_bank SET answer_text = 'Forecast using trend, seasonality and autoregressive structure (ARIMA, ETS, Prophet, gradient boosting). Pitfalls include random train-test splits (use time-based), non-stationarity, leakage, ignoring holidays or regime changes, and over-optimistic horizons.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain time series forecasting and common pitfalls.';
UPDATE question_bank SET answer_text = 'K-means partitions data into k roughly spherical clusters and needs k specified. DBSCAN finds dense regions, discovers arbitrary shapes, labels noise and needs no k, but is sensitive to its density parameters.' WHERE job_role = 'Data Scientist' AND question_text = 'What is the difference between clustering algorithms like K-means and DBSCAN?';
UPDATE question_bank SET answer_text = 'Package the model with reproducible code and environment, serve it via a batch job or API, add input validation, versioning, tests and CI/CD, then monitor performance and drift and plan retraining.' WHERE job_role = 'Data Scientist' AND question_text = 'How would you productionize a machine learning model?';
UPDATE question_bank SET answer_text = 'Model drift is when data or relationships change so the model degrades. Monitor input distributions (PSI, KS tests), prediction distributions and, when labels arrive, performance, with alerts and a retraining plan.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain model drift and how you would monitor for it in production.';
UPDATE question_bank SET answer_text = 'Aggregations with GROUP BY, window functions, CTEs, joins, CASE expressions, date functions, distinct counts, percentiles and sampling to profile distributions, nulls and duplicates.' WHERE job_role = 'Data Scientist' AND question_text = 'What SQL techniques do you use most often for exploratory data analysis?';
UPDATE question_bank SET answer_text = 'Use prediction intervals, confidence ranges or probabilities instead of single numbers, show them visually, explain what drives uncertainty in plain language, and tie it to decision risk.' WHERE job_role = 'Data Scientist' AND question_text = 'How do you communicate uncertainty in your model''s predictions to stakeholders?';
UPDATE question_bank SET answer_text = 'The ROC curve plots true positive rate against false positive rate across thresholds. AUC is the area under it: the probability the model ranks a random positive above a random negative; 0.5 is chance and 1.0 is perfect.' WHERE job_role = 'Data Scientist' AND question_text = 'Explain the ROC curve and what AUC represents.';
UPDATE question_bank SET answer_text = 'Python with pandas, scikit-learn, XGBoost and PyTorch or TensorFlow for modeling; SQL for data; MLflow for tracking; Docker, FastAPI and cloud services for deployment; and Airflow or similar for orchestration.' WHERE job_role = 'Data Scientist' AND question_text = 'What tools or frameworks do you typically use for building and deploying models?';

-- ===== DATA SCIENTIST: SITUATIONAL =====
UPDATE question_bank SET answer_text = 'I would politely decline to misrepresent the findings, explain what the data does and does not support, and offer to present the result honestly with context or run further analysis. Integrity protects both the business and my credibility.' WHERE job_role = 'Data Scientist' AND question_text = 'A stakeholder wants you to make a model''s results say something the data doesn''t support. How do you respond?';
UPDATE question_bank SET answer_text = 'Check for training-serving skew, data drift, leakage in testing, differences in feature pipelines and sample mismatch. Compare distributions, replay production data and fix the cause, then add monitoring.' WHERE job_role = 'Data Scientist' AND question_text = 'Your model performs well in testing but poorly in production. How do you investigate?';
UPDATE question_bank SET answer_text = 'Triage the issues by impact, fix or exclude the worst data, document assumptions and limitations, deliver a smaller defensible result on time, and tell stakeholders about the uncertainty.' WHERE job_role = 'Data Scientist' AND question_text = 'You''re given a dataset with significant quality issues and a tight deadline. What do you do?';
UPDATE question_bank SET answer_text = 'Listen to their concerns, walk through methodology and evidence, check if they know something I missed, and be open to revising. Offer additional analysis that addresses their doubts.' WHERE job_role = 'Data Scientist' AND question_text = 'A business team disagrees with your analysis conclusions. How do you handle the pushback?';
UPDATE question_bank SET answer_text = 'Lead with the business problem and outcome, use analogies and visuals, explain what drives predictions without math, state limitations and risks, and give a clear recommendation.' WHERE job_role = 'Data Scientist' AND question_text = 'You need to explain a complex model to non-technical executives. How do you approach it?';
UPDATE question_bank SET answer_text = 'Present the result honestly: no detectable difference yet, with the confidence interval. Offer options such as extending the test, choosing based on cost or risk, or a staged rollout, and let leadership decide with clear trade-offs.' WHERE job_role = 'Data Scientist' AND question_text = 'Your A/B test results are inconclusive, but leadership wants a decision now. What do you do?';
UPDATE question_bank SET answer_text = 'Quantify the bias, report it to my lead and relevant stakeholders, and mitigate through rebalancing, new data or fairness constraints. Document it and add monitoring before release.' WHERE job_role = 'Data Scientist' AND question_text = 'You discover your training data contains a bias that could harm certain user groups. What''s your next step?';
UPDATE question_bank SET answer_text = 'Check for data drift, concept drift, upstream pipeline changes and seasonality. Compare recent and old data, segment errors, and then retrain or adjust features with ongoing monitoring.' WHERE job_role = 'Data Scientist' AND question_text = 'A model you built starts degrading in performance over time. How do you diagnose the cause?';
UPDATE question_bank SET answer_text = 'Raise my reliability concerns with evidence, quantify the likely impact, deliver insights with clear caveats or confidence levels, and recommend improving the data source.' WHERE job_role = 'Data Scientist' AND question_text = 'You''re asked to deliver insights from data you believe is unreliable. How do you proceed?';
UPDATE question_bank SET answer_text = 'Decide which one is testable with available data, compare cost and potential impact, run quick checks that could falsify each, and pursue the one with stronger early evidence while noting the alternative.' WHERE job_role = 'Data Scientist' AND question_text = 'Two competing hypotheses both seem plausible from your analysis. How do you decide which to pursue?';
UPDATE question_bank SET answer_text = 'Be transparent early: show what is achievable with the data, use simpler models, augmentation or transfer learning, propose collecting more data, and give realistic accuracy ranges with a phased plan.' WHERE job_role = 'Data Scientist' AND question_text = 'You have limited data to train a model that the business insists must be highly accurate. How do you manage expectations?';
UPDATE question_bank SET answer_text = 'Reproduce their analysis to confirm my concern, then raise it privately and constructively with specifics and suggestions, assuming I may be missing something. Escalate only if it remains unresolved.' WHERE job_role = 'Data Scientist' AND question_text = 'A colleague''s analysis reaches a conclusion you believe is statistically flawed. How do you address it?';
UPDATE question_bank SET answer_text = 'Compare expected business value, urgency and risk. Deliver the quick report first if there is a deadline, then time-box exploration of the new technique, and share the plan with my manager.' WHERE job_role = 'Data Scientist' AND question_text = 'You''re asked to prioritize between exploring a new modeling technique and delivering a quick business report. How do you decide?';
UPDATE question_bank SET answer_text = 'Involve stakeholders early, use interpretable explanations such as feature importance, validate against known cases, share performance transparently with limitations, and run a pilot so they see it work.' WHERE job_role = 'Data Scientist' AND question_text = 'Your model''s predictions are technically correct but stakeholders don''t trust them. How do you build trust?';
UPDATE question_bank SET answer_text = 'Report it immediately, quantify which reports and periods are affected, fix the bug, backfill corrected data, notify downstream users and add validation tests and alerts.' WHERE job_role = 'Data Scientist' AND question_text = 'You find a data pipeline bug that has been silently corrupting reports for months. What do you do?';
UPDATE question_bank SET answer_text = 'Explain the specific risks to the business, propose a streamlined testing plan such as a shadow mode or limited rollout, and document the risk if they still choose to proceed.' WHERE job_role = 'Data Scientist' AND question_text = 'Leadership wants to skip proper testing to rush a model into production. How do you respond?';
UPDATE question_bank SET answer_text = 'Talk to domain experts, read key documentation and past analyses, learn the main metrics and terms, and validate my understanding by reviewing findings with an expert.' WHERE job_role = 'Data Scientist' AND question_text = 'You''re asked to analyze a dataset outside your usual domain expertise. How do you get up to speed quickly?';
UPDATE question_bank SET answer_text = 'Double-check the analysis, present the facts neutrally with context and evidence, brief key stakeholders privately before a wider audience, and focus on implications and options.' WHERE job_role = 'Data Scientist' AND question_text = 'Your analysis reveals a sensitive or controversial finding about the business. How do you present it?';
UPDATE question_bank SET answer_text = 'Approach it as a neutral, fact-finding exercise: review data, assumptions and deployment details, reproduce results and look at root causes beyond the model. Share findings collaboratively with the other team.' WHERE job_role = 'Data Scientist' AND question_text = 'A model built by another team is being blamed for a bad business outcome. How do you investigate objectively?';
UPDATE question_bank SET answer_text = 'Learn their constraints and goals, agree on shared success measures and interfaces, communicate in their language, involve them early and hold regular syncs.' WHERE job_role = 'Data Scientist' AND question_text = 'You need to collaborate with engineers who have very different priorities than your data science team. How do you align?';
UPDATE question_bank SET answer_text = 'Gather each team''s definition and use case, agree on one canonical definition with a data owner, document it in a metrics layer or glossary, and rename variants clearly.' WHERE job_role = 'Data Scientist' AND question_text = 'You have conflicting definitions of a key metric across teams. How do you resolve it?';
UPDATE question_bank SET answer_text = 'Document the original scope, show the cost of additions, ask the sponsor to prioritize or extend time and resources, and move extras to a later phase.' WHERE job_role = 'Data Scientist' AND question_text = 'Your project''s scope keeps expanding without additional time or resources. How do you handle it?';
UPDATE question_bank SET answer_text = 'Talk to the stakeholders to see how they read it, add clear labels, definitions, annotations and caveats, simplify misleading visuals and offer a short walkthrough.' WHERE job_role = 'Data Scientist' AND question_text = 'A dashboard you built is being misread by stakeholders to draw wrong conclusions. What do you do?';
UPDATE question_bank SET answer_text = 'Check environment, versions, random seeds and data snapshots, ask the colleague for details, and work with them to find the difference. Document it so it is reproducible.' WHERE job_role = 'Data Scientist' AND question_text = 'You''re asked to reproduce a colleague''s results but can''t replicate them. How do you proceed?';
UPDATE question_bank SET answer_text = 'Consider regulatory needs, stakeholder trust, the accuracy gain versus risk and cost of errors. Start with a simple baseline, and use the complex model only if it clearly adds value, with explainability tools.' WHERE job_role = 'Data Scientist' AND question_text = 'You need to choose between a simple interpretable model and a complex, more accurate one. How do you decide?';
UPDATE question_bank SET answer_text = 'Respect their experience, present the evidence clearly, ask what they are seeing that the data might miss, and propose a small test to settle the question objectively.' WHERE job_role = 'Data Scientist' AND question_text = 'Your recommendation based on data analysis conflicts with a senior leader''s gut instinct. How do you handle it?';
UPDATE question_bank SET answer_text = 'Explain the difference between statistical and practical significance, translate the effect into business impact and cost, and advise whether it justifies rollout.' WHERE job_role = 'Data Scientist' AND question_text = 'A/B test results show statistical significance but the effect size is tiny. How do you advise the business?';
UPDATE question_bank SET answer_text = 'Do quick sanity checks on the key fields, document what is unvalidated, build a baseline, label results as preliminary and validate in parallel before anything is relied on.' WHERE job_role = 'Data Scientist' AND question_text = 'You''re asked to build a model quickly with data you haven''t had time to validate. What do you do?';
UPDATE question_bank SET answer_text = 'Use sampling, simpler models, efficient algorithms, cloud burst compute or incremental training, and prioritize experiments with the highest expected value.' WHERE job_role = 'Data Scientist' AND question_text = 'Your team lacks the compute resources needed for a project. How do you adapt your approach?';
UPDATE question_bank SET answer_text = 'Pause and go back to the stakeholders to clarify the real decision and success metric, explain what I found, agree on a refined question, and re-scope the work.' WHERE job_role = 'Data Scientist' AND question_text = 'You realize partway through a project that the original business question was poorly defined. What do you do?';

-- ===== PRODUCT MANAGER: TECHNICAL =====
UPDATE question_bank SET answer_text = 'Rank by impact versus effort using a framework like RICE, tie work to company goals, confirm what is critical with engineering, cut or defer low-value items, and look for smaller slices that deliver value sooner. Communicate the trade-offs openly.' WHERE job_role = 'Product Manager' AND question_text = 'How do you prioritize a product roadmap when you have limited engineering resources?';
UPDATE question_bank SET answer_text = 'State the problem and goals, target users, success metrics, scope and non-goals, user stories and requirements, designs, dependencies, risks, and launch plan. Keep it concise, review it with design and engineering, and update it as things change.' WHERE job_role = 'Product Manager' AND question_text = 'Walk me through how you would write a product requirements document (PRD).';
UPDATE question_bank SET answer_text = 'Product-market fit means a clear segment strongly values the product. Measure retention curves flattening, the Sean Ellis test (40% or more "very disappointed" without it), organic growth and word of mouth, NPS and willingness to pay.' WHERE job_role = 'Product Manager' AND question_text = 'How do you define and measure product-market fit?';
UPDATE question_bank SET answer_text = 'I mainly use RICE (reach, impact, confidence, effort) for comparability, MoSCoW for scope within a release, and sometimes Kano or value-versus-effort. The framework is a tool for discussion, not a replacement for judgment.' WHERE job_role = 'Product Manager' AND question_text = 'What framework do you use to prioritize features (e.g., RICE, MoSCoW)?';
UPDATE question_bank SET answer_text = 'Start from the product''s goal and user value, pick one north-star metric with supporting input metrics and guardrails, and make sure they are measurable, actionable and tied to business outcomes.' WHERE job_role = 'Product Manager' AND question_text = 'How do you decide which metrics matter most for a given product?';
UPDATE question_bank SET answer_text = 'Define the questions, recruit the right users, run interviews and usability tests, combine with survey and usage data, synthesize themes, and share findings that shape requirements.' WHERE job_role = 'Product Manager' AND question_text = 'Explain how you''d conduct user research before building a new feature.';
UPDATE question_bank SET answer_text = 'Look for solutions that serve both, such as a user-friendly feature that also drives revenue. If they truly conflict, quantify long-term impact on retention and trust versus short-term gains, and escalate with a clear recommendation.' WHERE job_role = 'Product Manager' AND question_text = 'How do you balance user needs with business goals when they conflict?';
UPDATE question_bank SET answer_text = 'Write stories as "As a [user], I want [goal] so that [benefit]", keep them small and testable, add acceptance criteria in clear given/when/then form, and review them with engineering and design.' WHERE job_role = 'Product Manager' AND question_text = 'Describe your approach to writing user stories and acceptance criteria.';
UPDATE question_bank SET answer_text = 'Build if it is core differentiation and we have the capability; buy or partner if it is commodity, speed matters, or the cost to build and maintain is higher. Compare total cost, time to market, control, risk and strategic fit.' WHERE job_role = 'Product Manager' AND question_text = 'How do you determine whether to build, buy, or partner for a capability?';
UPDATE question_bank SET answer_text = 'An MVP is the smallest version that tests the core value hypothesis with real users. Scope it by identifying the key problem and riskiest assumption, cutting everything that does not test it, and defining success criteria first.' WHERE job_role = 'Product Manager' AND question_text = 'What is a minimum viable product, and how do you scope one?';
UPDATE question_bank SET answer_text = 'Map competitors and substitutes, compare offerings, pricing, positioning and customer reviews, find gaps and unmet needs, assess barriers, and define where we can differentiate.' WHERE job_role = 'Product Manager' AND question_text = 'How do you approach competitive analysis for a new market entry?';
UPDATE question_bank SET answer_text = 'Set an inspiring qualitative objective tied to strategy, with 2-4 measurable key results focused on outcomes, align with the team and leadership, and review progress regularly. Aim for ambitious but credible targets.' WHERE job_role = 'Product Manager' AND question_text = 'Explain how you would set OKRs for a product team.';
UPDATE question_bank SET answer_text = 'A feature ships when it meets the acceptance criteria and quality bar, solves the core problem, and risks are managed. Use beta feedback and metrics; iterate afterwards if issues are non-critical.' WHERE job_role = 'Product Manager' AND question_text = 'How do you decide when a feature is ready to ship versus needs more iteration?';
UPDATE question_bank SET answer_text = 'Combine cost-plus floors, competitor benchmarks and value-based pricing informed by willingness-to-pay research. Test price points and packaging with experiments, and consider the segments and monetization model.' WHERE job_role = 'Product Manager' AND question_text = 'Describe your approach to pricing a new product or feature.';
UPDATE question_bank SET answer_text = 'Treat technical debt as a real investment: reserve a share of capacity each cycle, prioritize the debt that slows delivery or poses risk, and explain its business impact so stakeholders support it.' WHERE job_role = 'Product Manager' AND question_text = 'How do you handle technical debt trade-offs when planning a roadmap?';
UPDATE question_bank SET answer_text = 'Validate cheaply first: customer interviews, landing page or fake-door tests, prototypes and competitive data. Only commit engineering time once there is evidence of real demand.' WHERE job_role = 'Product Manager' AND question_text = 'What''s your process for validating a product idea before committing engineering time?';
UPDATE question_bank SET answer_text = 'Segment by needs, behavior, value and size, then prioritize segments that are large, underserved, strategically aligned and reachable, and validate through research and data.' WHERE job_role = 'Product Manager' AND question_text = 'How do you approach segmenting users to prioritize which needs to address first?';
UPDATE question_bank SET answer_text = 'Define goals and success criteria, recruit a representative group, give them the feature with a feedback channel, track usage and issues, iterate, and decide on launch from the results.' WHERE job_role = 'Product Manager' AND question_text = 'Explain how you would run a beta test for a new feature.';
UPDATE question_bank SET answer_text = 'Say no to things that do not serve the strategy or core users, have low impact for high cost, or are one-off requests. I keep a visible "not now" list with reasons.' WHERE job_role = 'Product Manager' AND question_text = 'How do you decide what NOT to build?';
UPDATE question_bank SET answer_text = 'Group users by sign-up date or first action and track retention, engagement or revenue over time. Compare cohorts before and after a change to see whether it improved behavior, avoiding mixing old and new users.' WHERE job_role = 'Product Manager' AND question_text = 'Describe how you would use cohort analysis to evaluate product changes.';
UPDATE question_bank SET answer_text = 'Set up reliable tracking and an experimentation platform, define hypotheses and metrics up front, calculate sample size, randomize properly, run for a full cycle and review results with guardrail metrics before deciding.' WHERE job_role = 'Product Manager' AND question_text = 'How do you approach setting up experimentation and A/B testing for product decisions?';
UPDATE question_bank SET answer_text = 'Collect from many channels (support, sales, interviews, surveys, usage data), tag and cluster themes, weigh by frequency and customer value, and share insights with the team to inform priorities.' WHERE job_role = 'Product Manager' AND question_text = 'What''s your process for gathering and synthesizing customer feedback?';
UPDATE question_bank SET answer_text = 'Look at usage, maintenance cost, strategic fit and revenue impact, and who depends on it. If it should go, communicate early, offer migration paths and set a clear timeline.' WHERE job_role = 'Product Manager' AND question_text = 'How do you evaluate whether a product should sunset a feature?';
UPDATE question_bank SET answer_text = 'Involve design and engineering early, share the problem and context rather than solutions, plan together with shared milestones and clear roles, and keep regular syncs and open feedback loops.' WHERE job_role = 'Product Manager' AND question_text = 'Explain your approach to cross-functional planning with design and engineering.';
UPDATE question_bank SET answer_text = 'v1 should deliver the core value to the target user with acceptable quality. I list must-haves versus later items, based on research, effort and risk, and plan iterations from real feedback.' WHERE job_role = 'Product Manager' AND question_text = 'How do you decide on the scope of a v1 launch versus future iterations?';
UPDATE question_bank SET answer_text = 'Tie metrics to the product''s purpose: acquisition, activation, retention, engagement and revenue, with one north star and a few targets and guardrails. Set baselines and revisit as we learn.' WHERE job_role = 'Product Manager' AND question_text = 'Describe how you would define success metrics for a brand-new product.';
UPDATE question_bank SET answer_text = 'Research each market''s language, regulation, payment, cultural and usability needs; build internationalization into the product from the start; work with local experts and test with local users.' WHERE job_role = 'Product Manager' AND question_text = 'How do you approach international or localization considerations for a product?';
UPDATE question_bank SET answer_text = 'Understand the underlying need, check whether other customers share it and how it fits strategy, then decide using the normal prioritization process. Communicate honestly about the decision and timeline.' WHERE job_role = 'Product Manager' AND question_text = 'What''s your process for handling a feature request from a major customer?';
UPDATE question_bank SET answer_text = 'Use the funnel (acquisition, activation, conversion) to find where users drop off, and retention curves and cohort data to see whether users stick, then segment to find causes.' WHERE job_role = 'Product Manager' AND question_text = 'How do you evaluate the health of a product using funnel or retention metrics?';
UPDATE question_bank SET answer_text = 'Define target audience, positioning and messaging, channels, launch timeline, sales and support enablement, pricing and success metrics, and coordinate with marketing, sales and customer success.' WHERE job_role = 'Product Manager' AND question_text = 'Explain how you would structure a go-to-market plan for a new feature.';
UPDATE question_bank SET answer_text = 'Include enough detail to be unambiguous about behavior and constraints, but leave implementation choices to engineering. Tune detail to team seniority and the risk of the feature.' WHERE job_role = 'Product Manager' AND question_text = 'How do you decide the right level of technical detail to include in a PRD?';
UPDATE question_bank SET answer_text = 'Keep the backlog groomed and ordered by priority, with clear well-sized items, regularly remove stale ones, review it with the team and link items to goals.' WHERE job_role = 'Product Manager' AND question_text = 'Describe your approach to managing a product backlog.';
UPDATE question_bank SET answer_text = 'Weigh the cost of defects and rework against the cost of delay. Set a clear quality bar for critical areas, accept lower polish where risk is low, and use staged rollouts to manage risk.' WHERE job_role = 'Product Manager' AND question_text = 'How do you evaluate build quality trade-offs versus speed to market?';
UPDATE question_bank SET answer_text = 'Involve legal and compliance early, understand the requirements, design compliance into the product, document decisions and treat it as a non-negotiable constraint when prioritizing.' WHERE job_role = 'Product Manager' AND question_text = 'What''s your approach to handling regulatory or compliance constraints in product decisions?';
UPDATE question_bank SET answer_text = 'When research is rigorous, representative and consistent, I present it with evidence and the business impact. Stakeholder opinions are hypotheses to test, though I stay open to context they may know.' WHERE job_role = 'Product Manager' AND question_text = 'How do you decide when user research findings should override stakeholder opinions?';
UPDATE question_bank SET answer_text = 'Platform decisions build reusable capabilities with long-term leverage for many teams, while feature decisions deliver specific user value now. I weigh strategy, scale of reuse and cost, and make sure platform work is tied to concrete use cases.' WHERE job_role = 'Product Manager' AND question_text = 'Explain how you would approach platform versus feature-level product decisions.';
UPDATE question_bank SET answer_text = 'Quantitative data shows what and how much; qualitative shows why. I use quantitative data to find patterns and size problems, then qualitative research to understand causes and shape solutions.' WHERE job_role = 'Product Manager' AND question_text = 'How do you use qualitative versus quantitative data in product decisions?';
UPDATE question_bank SET answer_text = 'In introduction focus on validation, in growth on scaling acquisition and retention, in maturity on efficiency and defending share, and in decline on sunsetting or reinvention. I adapt strategy and metrics to each stage.' WHERE job_role = 'Product Manager' AND question_text = 'Describe your approach to managing a product through its lifecycle stages.';
UPDATE question_bank SET answer_text = 'Estimate benefit (revenue, retention, cost savings) using data and assumptions, compare with build and maintenance costs and opportunity cost, include uncertainty ranges and validate assumptions with tests.' WHERE job_role = 'Product Manager' AND question_text = 'How do you evaluate the ROI of a proposed feature before building it?';
UPDATE question_bank SET answer_text = 'Pivot when evidence shows the core assumptions are wrong despite iteration, such as persistent poor retention, while a pivot preserves what we have learned. I define signals and decision points in advance.' WHERE job_role = 'Product Manager' AND question_text = 'What''s your framework for deciding whether to pivot a product strategy?';

-- ===== PRODUCT MANAGER: SITUATIONAL =====
UPDATE question_bank SET answer_text = 'Understand why with engineering, look for a smaller scope that delivers the core value sooner, reassess priority with the new cost, and tell stakeholders early with options.' WHERE job_role = 'Product Manager' AND question_text = 'Engineering says a highly requested feature will take three times longer than planned. What do you do?';
UPDATE question_bank SET answer_text = 'Understand the real need behind the request, assess how many customers share it and the revenue at stake, explore alternatives or a workaround, and be honest about what we can commit to.' WHERE job_role = 'Product Manager' AND question_text = 'A key customer threatens to churn unless you build a specific feature. How do you respond?';
UPDATE question_bank SET answer_text = 'Look at funnel data to find where users drop off, talk to users, review the original hypothesis and delivery quality, then iterate, reposition or retire it.' WHERE job_role = 'Product Manager' AND question_text = 'Your team shipped a feature that''s underperforming. How do you diagnose why?';
UPDATE question_bank SET answer_text = 'Meet each privately to understand their reasoning, bring data and customer evidence, align on shared goals, and facilitate a decision, escalating to a common leader if needed.' WHERE job_role = 'Product Manager' AND question_text = 'Two senior stakeholders disagree on product direction. How do you navigate it?';
UPDATE question_bank SET answer_text = 'Stop and engage legal and engineering immediately, assess the gap and options, such as a delay, a reduced scope or a workaround, and brief leadership on risk and a plan.' WHERE job_role = 'Product Manager' AND question_text = 'You discover late in development that a feature won''t meet a regulatory requirement. What do you do?';
UPDATE question_bank SET answer_text = 'Understand the client''s need and deal value, assess fit with the roadmap, and give sales an honest answer on what can be promised. Align with leadership on exceptions and set a process to avoid unplanned promises.' WHERE job_role = 'Product Manager' AND question_text = 'Sales wants a feature promised to a client that isn''t on the roadmap. How do you handle it?';
UPDATE question_bank SET answer_text = 'Present the research respectfully with clear evidence and quotes, connect it to business outcomes, acknowledge their perspective, and propose a low-cost test to confirm.' WHERE job_role = 'Product Manager' AND question_text = 'User research contradicts what leadership believes customers want. How do you present it?';
UPDATE question_bank SET answer_text = 'Triage the bugs by severity and user impact, decide on a quality bar for launch, and compare the cost of delay with the cost of shipping with known issues. Recommend ship, phase or delay with data.' WHERE job_role = 'Product Manager' AND question_text = 'Your product launch date is at risk due to unresolved bugs. How do you decide whether to delay?';
UPDATE question_bank SET answer_text = 'Communicate early and honestly about the reason, give a clear timeline, offer alternatives or migration help, and listen to concerns to reduce disruption.' WHERE job_role = 'Product Manager' AND question_text = 'You have to sunset a feature that a small but vocal user group loves. How do you manage the transition?';
UPDATE question_bank SET answer_text = 'Bring both sides together to restate the user problem and constraints, explore options with data or a quick prototype, and then make a clear decision as the owner.' WHERE job_role = 'Product Manager' AND question_text = 'Engineering and design disagree on implementation approach for a feature you own. How do you mediate?';
UPDATE question_bank SET answer_text = 'Analyze it calmly: does it change customer needs or just perception? Stay focused on our strategy, and adjust the roadmap only if there is real customer or market evidence.' WHERE job_role = 'Product Manager' AND question_text = 'A competitor launches a feature that makes your current roadmap look outdated. What do you do?';
UPDATE question_bank SET answer_text = 'Clarify the intent, measure the user experience impact, and look for ways to grow the metric without harming the user experience. Raise the risks with leadership with data and propose guardrail metrics.' WHERE job_role = 'Product Manager' AND question_text = 'You''re given a mandate to grow a metric that might hurt user experience. How do you approach it?';
UPDATE question_bank SET answer_text = 'Rank projects by strategic value and impact, stop or pause the lowest-value ones, align with leadership on the trade-offs, and communicate clearly to the team.' WHERE job_role = 'Product Manager' AND question_text = 'Your team is stretched across too many projects. How do you decide what to cut?';
UPDATE question_bank SET answer_text = 'Diagnose with funnel data, user feedback and discoverability checks; fix awareness, onboarding or usability issues, and if adoption stays low, be willing to change or retire it.' WHERE job_role = 'Product Manager' AND question_text = 'A feature you championed is failing to gain adoption post-launch. What''s your next move?';
UPDATE question_bank SET answer_text = 'Be transparent: explain the context and reasons, what changes and what does not, how it affects current work, and invite questions, so the team understands and can adapt.' WHERE job_role = 'Product Manager' AND question_text = 'Leadership wants to change strategic direction mid-quarter. How do you communicate this to your team?';
UPDATE question_bank SET answer_text = 'Meet the stakeholders, map who decides what, clarify goals and metrics, review existing commitments and quickly gain alignment on a short list of priorities.' WHERE job_role = 'Product Manager' AND question_text = 'You inherit a product with unclear ownership and conflicting priorities. Where do you start?';
UPDATE question_bank SET answer_text = 'Triage the complaints, work with engineering on a hotfix or rollback, give support clear messaging and workarounds, communicate with affected customers, and do a retrospective.' WHERE job_role = 'Product Manager' AND question_text = 'Customer support is overwhelmed with complaints about a recent release. How do you respond?';
UPDATE question_bank SET answer_text = 'Understand their goals and incentives, show how the work helps them, involve them early in shaping it, ask for specific small commitments and credit their contributions.' WHERE job_role = 'Product Manager' AND question_text = 'You need buy-in from a team that doesn''t report to you. How do you build alignment?';
UPDATE question_bank SET answer_text = 'Look for the explanation: maybe different segments, vanity usage or a good-enough-but-disliked workflow. Dig into the data and interviews, then resolve with a targeted test.' WHERE job_role = 'Product Manager' AND question_text = 'Data shows a feature is popular, but customer interviews say people hate it. How do you reconcile this?';
UPDATE question_bank SET answer_text = 'Identify the key unknowns, gather the fastest available evidence, choose the reversible option, state assumptions and risks, and set a checkpoint to review.' WHERE job_role = 'Product Manager' AND question_text = 'You''re asked to make a decision with incomplete data and a tight deadline. How do you proceed?';
UPDATE question_bank SET answer_text = 'Acknowledge the idea, show how it compares with current priorities, add it to the backlog through the standard process, and agree on a clear channel for requests.' WHERE job_role = 'Product Manager' AND question_text = 'A stakeholder keeps requesting new features outside of your prioritization process. How do you manage them?';
UPDATE question_bank SET answer_text = 'Reassess whether our differentiation, speed or quality still wins, and whether to accelerate, adjust positioning or deliver something distinct. Do not panic; use customer insight and brief leadership.' WHERE job_role = 'Product Manager' AND question_text = 'You discover a competitor is about to launch something similar to your unreleased feature. What do you do?';
UPDATE question_bank SET answer_text = 'Understand the request and urgency, assess the impact on current work, present the trade-offs to the executive and team, and reprioritize explicitly with what moves.' WHERE job_role = 'Product Manager' AND question_text = 'Your roadmap is disrupted by an urgent executive request. How do you reprioritize?';
UPDATE question_bank SET answer_text = 'Look into why: the metric may capture short-term behavior while feedback signals long-term risk. Examine guardrail metrics and segments, run follow-up research, and decide based on the long-term value.' WHERE job_role = 'Product Manager' AND question_text = 'A/B test results favor a design that user feedback suggests customers dislike. How do you decide?';
UPDATE question_bank SET answer_text = 'Be direct and respectful: explain the reasons, acknowledge the team''s effort, highlight what was learned and reuse it, and clearly describe what is next.' WHERE job_role = 'Product Manager' AND question_text = 'You need to kill a project that the team has invested months in. How do you handle the conversation?';
UPDATE question_bank SET answer_text = 'Ask what makes it infeasible, explore alternatives such as a reduced scope or a phased approach, and decide together on the best path to the user outcome.' WHERE job_role = 'Product Manager' AND question_text = 'Engineering pushes back that a requested feature isn''t technically feasible as scoped. How do you respond?';
UPDATE question_bank SET answer_text = 'Define the segments by value and strategy, understand each need, find common ground and sequence work. Where they conflict, prioritize the segment most aligned with our strategy and consider configurable options.' WHERE job_role = 'Product Manager' AND question_text = 'You''re managing a product with users in very different segments with conflicting needs. How do you prioritize?';
UPDATE question_bank SET answer_text = 'Verify the data, break it down by segment, platform and funnel step, check release changes and external factors, roll back if needed and communicate updates.' WHERE job_role = 'Product Manager' AND question_text = 'A key metric drops unexpectedly after a release. How do you investigate and respond?';
UPDATE question_bank SET answer_text = 'Learn their priorities, prepare a clear narrative linking the roadmap to strategy and data, be ready to explain trade-offs and invite their input.' WHERE job_role = 'Product Manager' AND question_text = 'You''re asked to justify your roadmap to a skeptical new executive. How do you prepare?';
UPDATE question_bank SET answer_text = 'Listen to the team''s concerns, explain the context behind the decision, be honest about my own view where appropriate, and focus on executing well and raising unresolved concerns upward.' WHERE job_role = 'Product Manager' AND question_text = 'Your team disagrees with a decision from leadership that you have to implement. How do you lead through it?';

-- ===== MARKETING MANAGER: TECHNICAL =====
UPDATE question_bank SET answer_text = 'Define the target customer and problem, research the market and competitors, set positioning and pricing, choose channels, plan messaging and launch phases with sales enablement, and set metrics and a feedback loop.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you develop a go-to-market strategy for a new product?';
UPDATE question_bank SET answer_text = 'Start with goals and expected return, allocate by past channel performance and strategic priorities, reserve a test budget and contingency, and track spend versus results monthly to reallocate.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain how you''d build and manage a marketing budget across channels.';
UPDATE question_bank SET answer_text = 'Tie metrics to the campaign goal: reach and engagement for awareness; CTR, conversion rate, CPL and CAC for performance; and pipeline, revenue and ROI as the ultimate measures.' WHERE job_role = 'Marketing Manager' AND question_text = 'What metrics do you use to measure campaign performance?';
UPDATE question_bank SET answer_text = 'Segment by demographics, behavior, needs and value using CRM and analytics data, choose segments that are large, reachable and valuable, and tailor message and channel for each.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you approach segmenting an audience for a targeted campaign?';
UPDATE question_bank SET answer_text = 'Brand marketing builds long-term awareness and preference, and is measured by awareness and sentiment; performance marketing drives measurable immediate actions such as clicks and sales. Strong strategies use both.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain the difference between brand marketing and performance marketing.';
UPDATE question_bank SET answer_text = 'CAC is total sales and marketing spend divided by the number of new customers in a period. It matters because it shows efficiency and, compared with lifetime value, whether growth is profitable.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you calculate customer acquisition cost (CAC) and why does it matter?';
UPDATE question_bank SET answer_text = 'Define goals and audience, research topics and keywords, build pillar and supporting content, set a calendar and distribution plan, and measure traffic, engagement and conversion to refine.' WHERE job_role = 'Marketing Manager' AND question_text = 'What''s your approach to building a content marketing strategy?';
UPDATE question_bank SET answer_text = 'Set up attribution and tracking, measure revenue or leads against cost per channel, identify the best performers, test improvements in creative, audience and landing pages, and shift spend towards what works.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you measure and improve marketing ROI?';
UPDATE question_bank SET answer_text = 'Do a technical audit, research keywords and intent, fix site structure and speed, create quality content, build authoritative links, and track rankings, traffic and conversions.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain how you would run an SEO strategy from scratch.';
UPDATE question_bank SET answer_text = 'Set goals, define audience and positioning, build a timeline with owners, prepare messaging and assets, coordinate channels and sales enablement, launch, then monitor results and optimize.' WHERE job_role = 'Marketing Manager' AND question_text = 'What''s your process for planning and executing a product launch campaign?';
UPDATE question_bank SET answer_text = 'Form a hypothesis, test one variable at a time with a large enough sample and random split, run for a full cycle, evaluate significance and apply learnings.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you approach A/B testing in marketing campaigns?';
UPDATE question_bank SET answer_text = 'The journey runs from awareness to consideration, decision, purchase and advocacy. Marketing supplies content and channels for each stage, such as ads and SEO early, case studies and demos in the middle, and offers and onboarding later.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain the customer journey and how marketing touches each stage.';
UPDATE question_bank SET answer_text = 'Rank channels by past ROI and audience fit, focus on two or three with the best returns, test small elsewhere, and measure CAC and conversion before scaling.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you decide which marketing channels to prioritize with limited budget?';
UPDATE question_bank SET answer_text = 'Define target audience, the category, the key benefit and the reason to believe, set it against competitors, and write a clear statement: "For [audience], [brand] is the [category] that [benefit] because [proof]."' WHERE job_role = 'Marketing Manager' AND question_text = 'What''s your approach to building a brand positioning statement?';
UPDATE question_bank SET answer_text = 'Build personas from real research and data, then use them to tailor messaging, creative, channels and offers, and keep them updated with campaign results.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you use customer personas in campaign planning?';
UPDATE question_bank SET answer_text = 'Brand awareness is measured by reach, impressions, search volume, surveys and share of voice; direct response by clicks, leads, conversions and sales. Match each to the campaign goal and timeframe.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain how you''d measure brand awareness versus direct response results.';
UPDATE question_bank SET answer_text = 'Segment by behavior, lifecycle stage and interests, build automated workflows such as welcome, nurture and re-engagement, personalize, and test subject lines and timing while monitoring open, click and unsubscribe rates.' WHERE job_role = 'Marketing Manager' AND question_text = 'What''s your approach to email marketing segmentation and automation?';
UPDATE question_bank SET answer_text = 'Compare CTR, conversion rate, CPA and ROAS against goals and benchmarks, check audience and creative performance, and optimize or pause underperformers.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you evaluate whether a paid ad campaign is performing well?';
UPDATE question_bank SET answer_text = 'Understand competitors'' claims, find our true differentiators that matter to customers, and craft messages that highlight them with proof, without attacking competitors.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain your approach to competitive positioning in marketing messaging.';
UPDATE question_bank SET answer_text = 'Choose partners whose audience matches ours and who are credible, set clear goals and tracking such as codes and UTMs, agree on disclosure rules, and measure results versus cost.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you approach influencer or partnership marketing?';
UPDATE question_bank SET answer_text = 'Use interviews, surveys, social listening, reviews, sales and support input and analytics, then turn the language customers use into messaging and test it.' WHERE job_role = 'Marketing Manager' AND question_text = 'What''s your process for gathering customer insights to inform messaging?';
UPDATE question_bank SET answer_text = 'LTV is the average revenue (or margin) per customer times expected lifespan. It lets marketing decide how much it can afford to spend to acquire customers, ideally LTV to CAC of 3:1 or better.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you measure the lifetime value (LTV) of a customer, and why does it matter to marketing?';
UPDATE question_bank SET answer_text = 'B2B funnels are longer, with multiple stakeholders, focused on lead generation, nurture and sales alignment. B2C funnels are shorter and more emotional, focused on awareness, quick conversion and repeat purchase.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain how you''d structure a marketing funnel for a B2B versus B2C product.';
UPDATE question_bank SET answer_text = 'Research local culture, language, channels, regulation and competitors, adapt messaging and creative (not just translate), use local partners and test before scaling.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you approach localization for marketing in new geographic markets?';
UPDATE question_bank SET answer_text = 'Write a clear brief covering objective, audience, key message, deliverables, tone, mandatories, budget and timeline, discuss it in person, and agree on review stages.' WHERE job_role = 'Marketing Manager' AND question_text = 'What''s your process for briefing a creative or design team on a campaign?';
UPDATE question_bank SET answer_text = 'Combine paid (fast reach), owned (website, email, content that builds relationships) and earned (PR, word of mouth) based on audience behavior, goals, budget and measured performance.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you decide on the right marketing mix (paid, owned, earned media)?';
UPDATE question_bank SET answer_text = 'Track users consistently across channels with UTMs and a CRM, choose a model (first-touch, last-touch, multi-touch or data-driven) that fits the buying cycle, and validate with incrementality tests.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain how you''d set up attribution modeling across multiple channels.';
UPDATE question_bank SET answer_text = 'Respond quickly, pause scheduled content, acknowledge the issue sincerely, correct course with facts, coordinate with PR and leadership, and review lessons learned.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you approach crisis communication when a campaign backfires?';
UPDATE question_bank SET answer_text = 'Agree shared goals and definitions of a qualified lead, plan campaigns together, give sales the right content, and review pipeline performance in regular meetings.' WHERE job_role = 'Marketing Manager' AND question_text = 'What''s your process for aligning marketing campaigns with sales goals?';
UPDATE question_bank SET answer_text = 'Start from needs and gaps, compare options on features, integration, cost, security and support, run a trial with real use cases and get team input.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you evaluate marketing technology (MarTech) tools before adopting them?';
UPDATE question_bank SET answer_text = 'Pick platforms where the audience is, adapt the content format and tone for each, set a posting and engagement rhythm, use paid support where useful and track engagement and conversions.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain your approach to social media strategy across different platforms.';
UPDATE question_bank SET answer_text = 'Set pre-defined thresholds for key metrics, check whether optimization has been tried, compare against benchmarks and opportunity cost, then pause or reallocate with a documented rationale.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you use data to decide when to sunset an underperforming campaign?';
UPDATE question_bank SET answer_text = 'Find newsworthy angles, build relationships with relevant journalists, craft concise pitches, prepare spokespeople and track coverage and its impact on traffic and awareness.' WHERE job_role = 'Marketing Manager' AND question_text = 'What''s your approach to public relations and media outreach?';
UPDATE question_bank SET answer_text = 'Set baselines before launch and track awareness, perception, consistency, engagement and business metrics such as sales or customer acquisition after, using surveys and analytics.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you measure the effectiveness of a rebrand?';
UPDATE question_bank SET answer_text = 'Set goals up front, track leads, meetings and pipeline from the event, add costs of booth, travel and staff, and compare against the revenue influenced.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain how you''d approach event marketing and measuring its ROI.';
UPDATE question_bank SET answer_text = 'Start with the elements with the biggest likely impact, such as headline, offer and call to action, based on analytics, heatmaps and user feedback, and test one change at a time.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you decide what to test first when optimizing a landing page?';
UPDATE question_bank SET answer_text = 'Work backwards from the revenue target using conversion rates at each funnel stage, average deal size and lead-to-close time, then add buffers and adjust with actuals.' WHERE job_role = 'Marketing Manager' AND question_text = 'What''s your process for forecasting demand generation targets?';
UPDATE question_bank SET answer_text = 'Use sustained nurture with educational content, engage multiple stakeholders, keep sales and marketing aligned, and measure engagement and pipeline progression, not just immediate conversions.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you approach marketing for a product with a long sales cycle?';
UPDATE question_bank SET answer_text = 'Set clear goals, KPIs and scope, communicate with detailed briefs and regular reviews, hold them accountable with reporting, and treat them as partners.' WHERE job_role = 'Marketing Manager' AND question_text = 'Explain your approach to managing an external marketing agency.';
UPDATE question_bank SET answer_text = 'Follow platform updates and trusted industry sources, join communities, attend webinars, get certifications and test changes in small experiments.' WHERE job_role = 'Marketing Manager' AND question_text = 'How do you stay current with changes in digital marketing platforms and algorithms?';

-- ===== MARKETING MANAGER: SITUATIONAL =====
UPDATE question_bank SET answer_text = 'Diagnose with data: audience, creative, offer, landing page and tracking. Make quick optimizations, shift budget from weak segments to strong ones, and set a threshold for pausing.' WHERE job_role = 'Marketing Manager' AND question_text = 'A campaign you launched is underperforming halfway through its budget. What do you do?';
UPDATE question_bank SET answer_text = 'Work with sales to review samples of leads, check qualification criteria and follow-up speed, adjust targeting and scoring, and agree on a shared definition of a good lead.' WHERE job_role = 'Marketing Manager' AND question_text = 'Sales says the leads marketing generates aren''t converting. How do you address it?';
UPDATE question_bank SET answer_text = 'Share my concern with data or research respectfully, ask about their reasoning, propose a small test or alternative, and align on the decision, then commit to execute well.' WHERE job_role = 'Marketing Manager' AND question_text = 'Your CEO wants to launch a campaign you believe targets the wrong audience. How do you respond?';
UPDATE question_bank SET answer_text = 'Stay calm, check how closely they copy and whether there is real harm, and double down on what makes us distinct. Consider legal advice only if actual infringement occurs.' WHERE job_role = 'Marketing Manager' AND question_text = 'A competitor launches an aggressive campaign copying your brand messaging. What''s your response?';
UPDATE question_bank SET answer_text = 'Protect the highest-ROI channels, pause the weakest, shift to lower-cost tactics such as owned channels, and communicate the revised plan and expected impact.' WHERE job_role = 'Marketing Manager' AND question_text = 'Your budget gets cut by 30% mid-quarter. How do you reprioritize spend?';
UPDATE question_bank SET answer_text = 'Pause scheduled posts, assess the nature and scale of the criticism, respond promptly and sincerely with a clear acknowledgement, take action to fix the issue, coordinate with PR and leadership, and review the approval process.' WHERE job_role = 'Marketing Manager' AND question_text = 'A social media post from your brand receives significant public backlash. How do you handle it?';
UPDATE question_bank SET answer_text = 'Use finance''s language: set up attribution, report revenue, CAC, payback and LTV, be open about what is measurable and what is not, and agree on metrics together.' WHERE job_role = 'Marketing Manager' AND question_text = 'You''re asked to prove marketing''s ROI to a skeptical finance team. How do you approach it?';
UPDATE question_bank SET answer_text = 'Check tracking first, then audience saturation, algorithm or policy changes, competitor activity, creative fatigue and seasonality, and test fixes while diversifying channels.' WHERE job_role = 'Marketing Manager' AND question_text = 'A key channel that historically drove results suddenly stops performing. What do you investigate?';
UPDATE question_bank SET answer_text = 'Research the culture deeply, work with local experts or agencies, test messaging with local audiences, and avoid assumptions, adapting language, imagery and channels.' WHERE job_role = 'Marketing Manager' AND question_text = 'You must launch a campaign in a market you have little cultural familiarity with. How do you prepare?';
UPDATE question_bank SET answer_text = 'Reschedule with new dates, keep teaser content flexible, tell partners and sales, redirect budget to warming up the audience and avoid making promises that cannot be kept.' WHERE job_role = 'Marketing Manager' AND question_text = 'Product delays push back your planned launch campaign. How do you adjust?';
UPDATE question_bank SET answer_text = 'Diversify to other channels and owned assets like email, test how the algorithm changes affect results, adapt content formats and avoid over-reliance on a single platform.' WHERE job_role = 'Marketing Manager' AND question_text = 'Your top-performing campaign relies heavily on one platform that changes its algorithm. What do you do?';
UPDATE question_bank SET answer_text = 'Look at the data: if the message converts better, test it in a controlled way and work with brand owners to adapt it within guidelines, balancing short-term results and long-term brand equity.' WHERE job_role = 'Marketing Manager' AND question_text = 'A stakeholder wants brand consistency, but data suggests a different message converts better. How do you decide?';
UPDATE question_bank SET answer_text = 'Stop and confirm the extent of the error, fix the data, assess what decisions and spend it affected, tell stakeholders openly and add data quality checks.' WHERE job_role = 'Marketing Manager' AND question_text = 'You discover inaccurate data has been driving your targeting for months. What''s your next step?';
UPDATE question_bank SET answer_text = 'Take it seriously: pause the copy, review the claim with legal, revise it with substantiated or qualified wording and update the review process.' WHERE job_role = 'Marketing Manager' AND question_text = 'Legal flags a claim in your campaign copy as potentially misleading. How do you handle it?';
UPDATE question_bank SET answer_text = 'Prioritize by business impact, negotiate scope and timing with leadership, share resources smartly, use agencies or freelancers where possible, and be clear about what will not be done.' WHERE job_role = 'Marketing Manager' AND question_text = 'Your team is asked to support three major launches simultaneously with the same resources. How do you manage it?';
UPDATE question_bank SET answer_text = 'Respond quickly and empathetically in public, offer to resolve it privately, involve customer support, fix the underlying issue and follow up.' WHERE job_role = 'Marketing Manager' AND question_text = 'A high-profile customer complains publicly about your brand. How do you respond?';
UPDATE question_bank SET answer_text = 'Send a short, clear correction promptly and apologize if appropriate, check for impact such as unsubscribes, and add safeguards like test sends and approval steps.' WHERE job_role = 'Marketing Manager' AND question_text = 'Your marketing automation platform sends an error email to your entire list. What do you do?';
UPDATE question_bank SET answer_text = 'Embrace the shift: learn the brand-building fundamentals, work with experts, define awareness metrics, and show how performance data can sharpen brand efforts.' WHERE job_role = 'Marketing Manager' AND question_text = 'Leadership wants to shift strategy toward brand awareness, away from your area of expertise in performance marketing. How do you adapt?';
UPDATE question_bank SET answer_text = 'Internal opinion is not the market, so analyze performance by audience and placement, run quick tests with real customers, gather feedback and iterate on the creative.' WHERE job_role = 'Marketing Manager' AND question_text = 'Your campaign''s creative tests well internally but underperforms with real customers. What''s your next move?';
UPDATE question_bank SET answer_text = 'Review the launch plan, redistribute tasks within the team, use freelancers or agencies where needed, prioritize critical items and brief stakeholders.' WHERE job_role = 'Marketing Manager' AND question_text = 'A key team member responsible for a launch leaves right before it goes live. How do you cover the gap?';
UPDATE question_bank SET answer_text = 'Do not react with a knee-jerk discount. Check the competitor''s offer in context, emphasize our value and differentiators, consider targeted offers for at-risk segments and align with sales and finance.' WHERE job_role = 'Marketing Manager' AND question_text = 'Your competitor undercuts your pricing right after your campaign launches. How do you respond?';
UPDATE question_bank SET answer_text = 'Show data on lead quality and conversion, involve them in designing criteria, pilot with a small group, and share results so the change is clearly in their interest.' WHERE job_role = 'Marketing Manager' AND question_text = 'You need buy-in from sales leadership for a campaign that changes how leads are qualified. How do you get alignment?';
UPDATE question_bank SET answer_text = 'Confirm the shift with data and research, rebuild personas, adapt messaging and channels, test with the new audience and phase out the old targeting.' WHERE job_role = 'Marketing Manager' AND question_text = 'Data shows your target audience has shifted, but current campaigns still target the old segment. What do you do?';
UPDATE question_bank SET answer_text = 'Present the data transparently and its implications, acknowledge the political context, propose a plan to improve or wind down gracefully, and avoid misrepresenting results.' WHERE job_role = 'Marketing Manager' AND question_text = 'You''re asked to justify continuing a campaign that the numbers say isn''t working, for political reasons. How do you handle it?';
UPDATE question_bank SET answer_text = 'Compare the work to the brief and give specific, constructive feedback, ask for revisions, and if it continues, escalate and improve the briefing process.' WHERE job_role = 'Marketing Manager' AND question_text = 'Your agency delivers creative that doesn''t match the brief. How do you address it?';
UPDATE question_bank SET answer_text = 'Decide quickly using relevance to our brand, tone, risk of backlash and speed of execution. If it fits naturally, act with an approved fast-track; if it feels forced, skip it.' WHERE job_role = 'Marketing Manager' AND question_text = 'A viral moment unrelated to your brand creates an opportunity for timely marketing. How do you decide whether to act?';
UPDATE question_bank SET answer_text = 'Agree on criteria linked to the goal and audience, test both concepts with a small audience or A/B test where possible, and decide based on evidence.' WHERE job_role = 'Marketing Manager' AND question_text = 'You have to choose between two campaign concepts your team is split on. How do you decide?';
UPDATE question_bank SET answer_text = 'Assess the timing conflict, shift or soften the planned campaign, align with communications and leadership, and update stakeholders and channels.' WHERE job_role = 'Marketing Manager' AND question_text = 'Your marketing calendar conflicts with an unplanned company announcement. How do you adjust?';
UPDATE question_bank SET answer_text = 'Check whether the test had enough power; if so, choose based on secondary metrics, cost, brand fit or ease, and test a bolder variation next.' WHERE job_role = 'Marketing Manager' AND question_text = 'A/B testing shows two variants performing almost identically. How do you decide what to do next?';
UPDATE question_bank SET answer_text = 'Identify which checks are critical (legal, brand, accuracy), run an expedited review for them, keep a clear approval owner, and add a rollback plan.' WHERE job_role = 'Marketing Manager' AND question_text = 'You''re asked to launch a campaign faster than your usual review process allows. How do you manage the risk?';

-- ===== SALES REPRESENTATIVE: TECHNICAL =====
UPDATE question_bank SET answer_text = 'Research and prospect, qualify, run discovery to uncover needs, demo or present a tailored solution, handle objections, send a proposal, negotiate, close, then hand off for onboarding and follow up for renewal and referrals.' WHERE job_role = 'Sales Representative' AND question_text = 'Walk me through your sales process from prospecting to close.';
UPDATE question_bank SET answer_text = 'Use a framework like BANT or MEDDIC: confirm a real problem, budget, decision-making authority, timeline and fit. Spend deep time only on leads that meet most criteria.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you qualify a lead before investing significant time?';
UPDATE question_bank SET answer_text = 'I use a consultative approach such as SPIN: ask about the Situation, Problem, Implication and Need-payoff so the buyer articulates the value themselves. MEDDIC helps on larger deals to map metrics, buyer and decision process.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain a sales methodology you use (e.g., SPIN, Challenger, MEDDIC).';
UPDATE question_bank SET answer_text = 'Review their company site, news, LinkedIn profile, financials or earnings, tech stack and competitors, and look for triggers like hiring or funding to craft a relevant opener.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you research a prospect before a first call?';
UPDATE question_bank SET answer_text = 'Define the ideal customer profile from past wins, filter by industry, size and signals, score accounts by fit and likelihood, and prioritize with CRM and tools like LinkedIn.' WHERE job_role = 'Sales Representative' AND question_text = 'What''s your approach to building a target account list?';
UPDATE question_bank SET answer_text = 'Do not discount immediately. Ask what they are comparing against, reinforce value and ROI, break the price down into outcomes, and consider flexible terms or a phased scope if necessary.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you handle a prospect who says the price is too high?';
UPDATE question_bank SET answer_text = 'Keep it short and personalized: a relevant hook from research, a clear value statement, one proof point, and a low-friction call to action, with a compelling subject line.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain your process for writing a compelling cold outreach email.';
UPDATE question_bank SET answer_text = 'Set an agenda, ask open-ended questions about goals, challenges, impact and process, listen actively, dig deeper on pain, confirm understanding and agree on next steps.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you structure a discovery call to uncover a prospect''s real needs?';
UPDATE question_bank SET answer_text = 'Be prepared, find common ground, listen more than I talk, show genuine curiosity and be honest and helpful from the first interaction.' WHERE job_role = 'Sales Representative' AND question_text = 'What''s your approach to building rapport quickly with a new prospect?';
UPDATE question_bank SET answer_text = 'Map the stakeholders and their priorities, tailor messages to each, find a champion, and align them around shared business outcomes with a mutual action plan.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you handle multiple decision-makers with different priorities in a deal?';
UPDATE question_bank SET answer_text = 'Weight pipeline by stage probabilities and historical conversion rates, check deal quality and timing, include coverage versus quota, and update weekly with realistic commit, best-case and upside categories.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain how you forecast your pipeline for a quarter.';
UPDATE question_bank SET answer_text = 'When there is no real pain, no access to a decision-maker, poor fit or unprofitable terms, and the time spent is better used elsewhere. I leave on good terms.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you decide when to walk away from a deal?';
UPDATE question_bank SET answer_text = 'Listen fully, acknowledge, ask a clarifying question to find the real concern, respond with evidence or examples and confirm that it is resolved.' WHERE job_role = 'Sales Representative' AND question_text = 'What''s your approach to handling objections during a sales pitch?';
UPDATE question_bank SET answer_text = 'Look at deal stage, size, close date, engagement and recent activity to prioritize, keep records accurate and use reports to spot stalled opportunities.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you use CRM data to prioritize which deals to focus on?';
UPDATE question_bank SET answer_text = 'Prepare priorities and limits, know the walk-away point, trade concessions for something in return, focus on value, not only price, and document everything.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain your process for negotiating contract terms.';
UPDATE question_bank SET answer_text = 'Understand how they use the product and their goals, identify gaps or growth, suggest relevant add-ons tied to results, and time it after a success.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you approach upselling or cross-selling to existing customers?';
UPDATE question_bank SET answer_text = 'Reach out with new value, such as a relevant insight, case study or change in their situation, use a different channel, and ask permission for a brief check-in.' WHERE job_role = 'Sales Representative' AND question_text = 'What''s your strategy for re-engaging a prospect who''s gone cold?';
UPDATE question_bank SET answer_text = 'Research their industry language, challenges and goals, and adapt the examples, value proposition and case studies for each persona, such as ROI for finance and ease of use for end users.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you tailor your pitch for different industries or buyer personas?';
UPDATE question_bank SET answer_text = 'Quantify costs, savings, revenue gains and payback using their numbers, state assumptions, compare to the cost of doing nothing and present it in finance''s format.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain how you build a business case to justify a purchase to a prospect''s finance team.';
UPDATE question_bank SET answer_text = 'Stay respectful, never trash a competitor, ask what they like about them, focus on our strengths for their needs and use proof such as customer references.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you handle a competitor being mentioned during a sales conversation?';
UPDATE question_bank SET answer_text = 'I rely on trial closes and assumptive next-step closes that follow from a clear agreement on value, such as summarizing needs and asking, "Shall we start with the pilot next week?" Pressure tactics hurt trust.' WHERE job_role = 'Sales Representative' AND question_text = 'What''s your approach to closing techniques, and which do you rely on most?';
UPDATE question_bank SET answer_text = 'Create a mutual action plan with milestones, maintain regular touchpoints, multi-thread across stakeholders, and keep sharing value to maintain momentum.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you manage a long sales cycle with multiple stakeholders?';
UPDATE question_bank SET answer_text = 'Send a recap within 24 hours with the agreed value and next steps, share relevant materials, answer open questions and schedule the next meeting.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain your process for following up after a demo.';
UPDATE question_bank SET answer_text = 'Ask happy customers for introductions at moments of success, make it easy with a short pre-written note, and thank them. Referrals convert better and faster.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you use referrals or existing customers to generate new business?';
UPDATE question_bank SET answer_text = 'Try different channels and times, send short value-adding messages, and finish with a polite "break-up" email that offers an easy way to respond.' WHERE job_role = 'Sales Representative' AND question_text = 'What''s your approach to handling a prospect who ghosts you after showing interest?';
UPDATE question_bank SET answer_text = 'Bring in specialists when the discussion gets technical, the deal is large or strategic, or a technical objection blocks progress, preferably after the business need is clear.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you determine the right time to loop in sales engineering or a specialist?';
UPDATE question_bank SET answer_text = 'Map the org and relationships, understand their goals and spend, identify opportunities and risks, set objectives and an engagement plan with owners, and review quarterly.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain your approach to account planning for key accounts.';
UPDATE question_bank SET answer_text = 'Allocate time deliberately: protect blocks for prospecting while scheduling regular account check-ins, and prioritize by potential revenue and risk.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you balance chasing new business with servicing existing accounts?';
UPDATE question_bank SET answer_text = 'Engage early, understand why they are at risk, bring in customer success and leadership if needed, show results and ROI, and offer solutions to fix the cause.' WHERE job_role = 'Sales Representative' AND question_text = 'What''s your process for handling a renewal at risk of churning?';
UPDATE question_bank SET answer_text = 'Optimize my profile, follow and engage with prospects'' content, share useful insights, make personalized connection requests and move conversations to calls.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you use social selling or LinkedIn in your prospecting?';
UPDATE question_bank SET answer_text = 'Tailor the demo to the discovery findings, show only what solves their stated problems, tell a story with outcomes, keep it interactive and end with clear next steps.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain your approach to running an effective product demo.';
UPDATE question_bank SET answer_text = 'Look at their size, headcount, usage, budget and roadmap, the number of potential users or departments, and what similar customers bought.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you determine deal size and expansion potential within an account?';
UPDATE question_bank SET answer_text = 'Segment accounts by potential and fit, set priorities and activity targets for each, plan travel or outreach cadence and review results regularly.' WHERE job_role = 'Sales Representative' AND question_text = 'What''s your approach to territory planning?';
UPDATE question_bank SET answer_text = 'Find the specific blockers, provide the documents they need early, find an internal champion to push, agree on timelines, and escalate with my manager if needed.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you handle a deal that stalls in procurement or legal review?';
UPDATE question_bank SET answer_text = 'Be transparent that I need approval, then build the case internally with the deal value and rationale, and meanwhile explore non-price alternatives like terms or scope.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain how you''d handle a prospect asking for a discount you''re not authorized to give.';
UPDATE question_bank SET answer_text = 'Prospect on a fixed daily schedule, use multiple channels, track pipeline coverage and conversion rates to know the activity needed, and keep nurturing and asking for referrals.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you keep your sales pipeline full consistently, month over month?';
UPDATE question_bank SET answer_text = 'Understand why they are unhappy with the incumbent, quantify switching costs and risk, offer a smooth migration plan and a low-risk pilot, and show proof from similar switches.' WHERE job_role = 'Sales Representative' AND question_text = 'What''s your approach to competitive displacement deals?';
UPDATE question_bank SET answer_text = 'Share relevant, similar-customer stories with specific results at the stage when the prospect needs proof, ideally with a reference call.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you use case studies or testimonials in your sales process?';
UPDATE question_bank SET answer_text = 'Involve legal, finance and executives early, define the value and a mutual plan, negotiate terms in order of priority, structure ramps or milestones, and manage the many stakeholders.' WHERE job_role = 'Sales Representative' AND question_text = 'Explain your process for handling a multi-year enterprise contract negotiation.';
UPDATE question_bank SET answer_text = 'Track activity, pipeline created, conversion rates, average deal size, sales cycle length, win rate and customer satisfaction or retention, in addition to closed revenue.' WHERE job_role = 'Sales Representative' AND question_text = 'How do you measure your own sales performance beyond just closed revenue?';

-- ===== SALES REPRESENTATIVE: SITUATIONAL =====
UPDATE question_bank SET answer_text = 'Check in with a helpful, low-pressure message, try another stakeholder, find out whether something changed, and ask directly if there is a concern I can address.' WHERE job_role = 'Sales Representative' AND question_text = 'A prospect goes silent right before signing. What do you do?';
UPDATE question_bank SET answer_text = 'Take a short moment, then ask for honest feedback on why, keep the relationship warm, review lessons, and refocus on the rest of the pipeline.' WHERE job_role = 'Sales Representative' AND question_text = 'Your biggest deal of the quarter falls through at the last minute. How do you recover?';
UPDATE question_bank SET answer_text = 'Listen to their concerns, acknowledge them, reinforce the value they get, explain the reasoning for the change and explore options such as phased pricing or a longer commitment.' WHERE job_role = 'Sales Representative' AND question_text = 'A customer threatens to churn over a pricing increase. How do you handle the conversation?';
UPDATE question_bank SET answer_text = 'Talk to the colleague and our manager promptly, check account ownership rules, and agree on who leads or how to collaborate so the customer is not confused.' WHERE job_role = 'Sales Representative' AND question_text = 'You discover a colleague is pursuing the same account as you. How do you resolve it?';
UPDATE question_bank SET answer_text = 'Be honest that it does not exist today, understand why they need it, show alternatives or workarounds, and share their feedback with product while not promising what is not planned.' WHERE job_role = 'Sales Representative' AND question_text = 'A prospect asks for a feature your product doesn''t have. How do you respond?';
UPDATE question_bank SET answer_text = 'Explain the risk of pushing too early with evidence, such as missing buyer commitments, propose a realistic plan to get ready, and respect the goal while protecting the customer relationship.' WHERE job_role = 'Sales Representative' AND question_text = 'Your manager wants you to push a deal to close before it''s ready. How do you handle it?';
UPDATE question_bank SET answer_text = 'Take ownership of the relationship, listen to the issue, coordinate with support and leadership for a fix with a timeline, and follow up regularly until resolved.' WHERE job_role = 'Sales Representative' AND question_text = 'A long-standing customer is unhappy with support and considering leaving. What do you do?';
UPDATE question_bank SET answer_text = 'Review the pipeline to find the deals closest to closing, focus effort there, re-engage warm leads, ask for referrals and be realistic in my forecast.' WHERE job_role = 'Sales Representative' AND question_text = 'You''re behind on quota with two weeks left in the quarter. How do you approach it?';
UPDATE question_bank SET answer_text = 'Stay calm, ask what they value in the competitor, acknowledge strengths honestly, redirect to how we address their specific needs and offer proof.' WHERE job_role = 'Sales Representative' AND question_text = 'A prospect compares you unfavorably to a competitor during a call. How do you respond?';
UPDATE question_bank SET answer_text = 'Correct it quickly and honestly with the customer, work with the team on what can be delivered, offer an alternative, and learn to check facts before promising.' WHERE job_role = 'Sales Representative' AND question_text = 'You realize you overpromised on a feature during a sales pitch. What''s your next step?';
UPDATE question_bank SET answer_text = 'Find who now holds the decision, rebuild the relationship with the new stakeholder and other contacts, and reconfirm the business case and timeline.' WHERE job_role = 'Sales Representative' AND question_text = 'A key stakeholder in a deal leaves the company mid-negotiation. How do you adapt?';
UPDATE question_bank SET answer_text = 'Be honest, explain the issue and any workaround or plan, say how it might affect them and let them decide with full information. Honesty protects trust and avoids churn later.' WHERE job_role = 'Sales Representative' AND question_text = 'Your product has a known issue that a prospect asks about directly. How do you handle it honestly?';
UPDATE question_bank SET answer_text = 'Understand why they need it, check with legal and management on what is acceptable, find a compromise within guidelines and be clear on timelines for approval.' WHERE job_role = 'Sales Representative' AND question_text = 'A prospect wants a custom contract term outside your standard terms. How do you proceed?';
UPDATE question_bank SET answer_text = 'Ask my champion for help getting a meeting, offer value targeted at the executive''s priorities, and consider involving my own leadership for executive-to-executive outreach.' WHERE job_role = 'Sales Representative' AND question_text = 'You''ve built strong rapport with a champion, but their boss is the real decision-maker and is unresponsive. What do you do?';
UPDATE question_bank SET answer_text = 'Tell them promptly and transparently, explain the reason, show the value that still applies, and discuss options such as honoring a quote for a limited time if possible.' WHERE job_role = 'Sales Representative' AND question_text = 'Your company changes pricing mid-negotiation with a prospect. How do you communicate it?';
UPDATE question_bank SET answer_text = 'Understand why they want the refund, review the contract and usage, involve the right internal teams, look for a solution such as support or a plan change, and handle it fairly and professionally.' WHERE job_role = 'Sales Representative' AND question_text = 'A customer wants a refund after using the product for months. How do you handle the request?';
UPDATE question_bank SET answer_text = 'Review the history, talk to the outgoing rep and customer, find what went wrong, and agree on a recovery plan with quick wins to rebuild trust.' WHERE job_role = 'Sales Representative' AND question_text = 'You''re asked to take over a struggling account from another rep. Where do you start?';
UPDATE question_bank SET answer_text = 'Ask my contact what is happening, offer help with the documents or approvals they need, find another route to the procurement team and reconfirm priority.' WHERE job_role = 'Sales Representative' AND question_text = 'A prospect''s procurement process suddenly stalls with no explanation. What do you do?';
UPDATE question_bank SET answer_text = 'Confirm what is being compared, avoid reflexive discounting, focus on total value, risk and outcomes, and involve management if a pricing exception is justified.' WHERE job_role = 'Sales Representative' AND question_text = 'You discover a competitor is offering a much lower price to your prospect. How do you respond?';
UPDATE question_bank SET answer_text = 'Understand the issues in advance, brief the CEO, bring facts and a solution plan, listen first and follow up with clear commitments.' WHERE job_role = 'Sales Representative' AND question_text = 'Your top customer requests a meeting with your CEO to discuss dissatisfaction. How do you prepare?';
UPDATE question_bank SET answer_text = 'Thank them, ask for honest feedback on why we lost, stay in touch, and apply the lessons to future deals. Many lost deals come back.' WHERE job_role = 'Sales Representative' AND question_text = 'A deal you were confident about gets lost to a competitor. How do you follow up?';
UPDATE question_bank SET answer_text = 'Plan ahead, prepare materials early, ask a colleague or manager to support one deal, and set clear expectations with each customer on timing.' WHERE job_role = 'Sales Representative' AND question_text = 'You have two high-priority deals closing on the same day and limited bandwidth. How do you manage both?';
UPDATE question_bank SET answer_text = 'Be honest that I will check, note the question, get the answer from an expert quickly and follow up the same day. Being honest builds credibility.' WHERE job_role = 'Sales Representative' AND question_text = 'A prospect asks a technical question you can''t answer confidently. What do you do?';
UPDATE question_bank SET answer_text = 'Do not rely on the notes alone; ask the previous rep if possible, verify directly with the prospect in discovery, and clean up the CRM record.' WHERE job_role = 'Sales Representative' AND question_text = 'Your CRM shows conflicting notes from a previous rep about a prospect. How do you proceed?';
UPDATE question_bank SET answer_text = 'Empathize, apologize for the experience, own getting it fixed by coordinating with billing, and update them until it is resolved, even if the cause is not mine.' WHERE job_role = 'Sales Representative' AND question_text = 'A customer is upset about a billing error unrelated to you. How do you handle their frustration?';
UPDATE question_bank SET answer_text = 'Study the product materials, shadow experienced colleagues, practice the pitch, and use specialists on early calls while I ramp up.' WHERE job_role = 'Sales Representative' AND question_text = 'You''re asked to sell a new product you have limited training on. How do you prepare?';
UPDATE question_bank SET answer_text = 'Engage legal early, provide standard documents and answers upfront, set clear timelines with them, and keep business momentum in parallel.' WHERE job_role = 'Sales Representative' AND question_text = 'A prospect wants to loop in their legal team, which historically slows deals significantly. How do you manage the timeline?';
UPDATE question_bank SET answer_text = 'Explain the business case to my manager and request an exception, explore non-price levers such as term length, scope or payment terms, and keep the customer informed.' WHERE job_role = 'Sales Representative' AND question_text = 'Your discount authority isn''t enough to close a deal a prospect wants. How do you proceed?';
UPDATE question_bank SET answer_text = 'Be honest with the lead and the referrer, avoid forcing a bad-fit sale, offer helpful guidance or a better-fitting option, and thank the referrer.' WHERE job_role = 'Sales Representative' AND question_text = 'A referral brings you a lead who turns out to be a poor fit for your product. How do you handle it?';
UPDATE question_bank SET answer_text = 'Build a target list, do heavy outreach, network and request introductions, set weekly activity goals, learn the market and quickly win a few early customers to create references.' WHERE job_role = 'Sales Representative' AND question_text = 'You''re new to a territory with no existing pipeline. How do you build momentum in the first 90 days?';

COMMIT;
